function wbAutomationPage(){
 const all=R.data.tasks.filter(t=>t.projectId===state.id),rows=all.filter(t=>(WB.taskStatus==='all'||t.status===WB.taskStatus)&&t.title.toLowerCase().includes(WB.taskQuery.toLowerCase()));
 return wbPageHead('自动化','管理定时执行的 Agent 任务，查看执行历史与结果')+`<div class="wb-agent-page-body"><div class="wb-automation-stats">${[['运行中','pulse'],['已暂停','pause'],['今日执行','plan'],['凭证过期','wrench']].map(([label,glyph])=>`<article><span>${icon(glyph)}${label}</span><b>—</b></article>`).join('')}</div><div class="wb-agent-toolbar"><input id="wb-task-query" aria-label="搜索任务标题" placeholder="搜索任务标题" value="${E(WB.taskQuery)}"><select id="wb-task-status" aria-label="任务状态">${[['all','全部'],['draft','待启用'],['paused','已暂停的草稿']].map(([id,label])=>`<option value="${id}" ${WB.taskStatus===id?'selected':''}>${label}</option>`).join('')}</select><span>共 ${all.length} 个任务</span><button class="solid wb-push-right" data-r-action="new-task">＋ 新建任务</button></div><div class="wb-agent-table"><table><thead><tr><th>任务</th><th>状态</th><th>调度</th><th>上次执行</th><th>操作</th></tr></thead><tbody>${rows.map(t=>`<tr><td><b>${E(t.title)}</b><small>${E(t.role||'默认 Agent')}</small></td><td>${t.status==='paused'?'草稿已暂停':'待启用'}</td><td>${E(t.schedule)}</td><td>未执行</td><td>${[['edit-task','编辑'],['pause-task',t.status==='paused'?'恢复':'暂停'],['task-history','记录'],['delete-task','删除']].map(([action,label])=>awButton(action,label,t.id)).join('')}</td></tr>`).join('')||'<tr><td colspan="5" class="wb-table-empty">没有数据</td></tr>'}</tbody></table></div><p class="wb-page-note">调度服务未连接，运行数据暂不可用；新建任务将保存为待启用草稿。</p></div>`;
}
const wbTaskDrawer=document.createElement('dialog');wbTaskDrawer.id='wb-task-drawer';wbTaskDrawer.setAttribute('aria-label','新建自动化任务');document.body.append(wbTaskDrawer);
function wbTaskSchedule(form){
 const trigger=form.elements.trigger.value,time=form.elements.time.value||'09:00';
 if(trigger==='一次性')return `${form.elements.date.value||new Date().toISOString().slice(0,10)} ${time} · Asia/Shanghai`;
 const frequency=form.elements.frequency.value,detail=frequency==='每周'?`每周${form.elements.weekday.value}`:frequency==='每月'?`每月 ${form.elements.monthday.value} 日`:frequency;
 return `${detail} ${time} · Asia/Shanghai`;
}
function wbDrawTaskForm(id){
 const task=R.data.tasks.find(t=>t.id===id)||{},once=task.trigger==='一次性',schedule=task.schedule||'',time=schedule.match(/\b\d{2}:\d{2}\b/)?.[0]||'09:00',date=schedule.match(/\d{4}-\d{2}-\d{2}/)?.[0]||new Date(Date.now()+86400000).toISOString().slice(0,10),frequency=schedule.startsWith('每周')?'每周':schedule.startsWith('每月')?'每月':'每天';
 wbTaskDrawer.innerHTML=`<form id="wb-task-form"><header><h2>${id?'编辑任务':'新建任务'}</h2><button type="button" id="wb-task-close" aria-label="关闭任务面板">×</button></header><main><section class="wb-task-field"><label>任务标题 <span id="wb-task-title-count">${[...(task.title||'')].length} 字</span></label><p>用一句话描述任务用途，便于在列表和侧栏中识别。</p><input name="title" required maxlength="60" value="${E(task.title||'')}" placeholder="例如：每周投放效果复盘"></section><section class="wb-task-field"><label>执行指令 <span id="wb-task-prompt-count">${[...(task.prompt||'')].length} 字</span></label><p>写清楚 Agent 到点要完成的目标、数据范围、输出格式和通知要求。</p><textarea name="prompt" required maxlength="2000" placeholder="例如：请统计过去 7 天各广告计划消耗、转化和 ROI，找出异常波动原因，并按结论、数据依据、建议动作输出。">${E(task.prompt||'')}</textarea></section><label class="wb-task-row"><span>Agent 角色</span><select name="role">${['默认营销 Agent','公关与知识库资源助手','设计 Agent'].map(role=>`<option ${role===(task.role||'默认营销 Agent')?'selected':''}>${role}</option>`).join('')}</select></label><label class="wb-task-row"><span>任务类型</span><select name="trigger"><option ${!once?'selected':''}>周期任务</option><option ${once?'selected':''}>一次性</option></select></label><section id="wb-task-cycle" class="wb-task-schedule" ${once?'hidden':''}><label><span>重复频率</span><select name="frequency"><option ${frequency==='每天'?'selected':''}>每天</option><option ${frequency==='每周'?'selected':''}>每周</option><option ${frequency==='每月'?'selected':''}>每月</option></select></label><label id="wb-task-weekday" ${frequency==='每周'?'':'hidden'}><span>执行日</span><select name="weekday">${['一','二','三','四','五','六','日'].map(day=>`<option ${schedule.includes('周'+day)?'selected':''}>${day}</option>`).join('')}</select></label><label id="wb-task-monthday" ${frequency==='每月'?'':'hidden'}><span>每月日期</span><input name="monthday" type="number" min="1" max="28" value="${schedule.match(/每月 (\d+)/)?.[1]||1}"></label></section><section id="wb-task-once" class="wb-task-schedule" ${once?'':'hidden'}><label><span>执行日期</span><input name="date" type="date" value="${date}"></label></section><label class="wb-task-row"><span>执行时间</span><input name="time" type="time" value="${time}" required></label><aside><b id="wb-task-preview"></b><small>触发精度约 ±1 分钟 · 时区 Asia/Shanghai</small></aside></main><footer><button type="button" id="wb-task-cancel">取消</button><button class="solid" type="submit">${id?'保存':'创建'}</button></footer></form>`;
 const form=$('#wb-task-form'),sync=()=>{const isOnce=form.elements.trigger.value==='一次性',repeat=form.elements.frequency.value;$('#wb-task-cycle').hidden=isOnce;$('#wb-task-once').hidden=!isOnce;$('#wb-task-weekday').hidden=isOnce||repeat!=='每周';$('#wb-task-monthday').hidden=isOnce||repeat!=='每月';$('#wb-task-preview').textContent='预览：'+wbTaskSchedule(form)+' 执行';};
 form.elements.title.oninput=()=>$('#wb-task-title-count').textContent=[...form.elements.title.value].length+' 字';form.elements.prompt.oninput=()=>$('#wb-task-prompt-count').textContent=[...form.elements.prompt.value].length+' 字';for(const input of form.querySelectorAll('select,input[type=date],input[type=time],input[type=number]'))input.onchange=sync;sync();
 $('#wb-task-close').onclick=$('#wb-task-cancel').onclick=()=>wbTaskDrawer.close();
 form.onsubmit=event=>{event.preventDefault();const values=Object.fromEntries(new FormData(form));values.schedule=wbTaskSchedule(form);values.notification=task.notification||'保存在 Agent 待办';if(id)Object.assign(task,values);else R.data.tasks.push({...values,id:uid(),projectId:state.id,status:'draft',created:now()});persist();wbTaskDrawer.close();if(page==='ad-agent')renderAssistant();else render();toast(id?'任务已保存':'任务已创建');};
}
R.taskForm=function(id){wbDrawTaskForm(id);if(!wbTaskDrawer.open)wbTaskDrawer.showModal();$('#wb-task-form [name=title]').focus();};
function wbTeamLog(action,target){workspace.knowledgeTeam.logs.unshift({action,target,operator:'张淼',time:new Date().toLocaleString('zh-CN',{hour12:false}).replaceAll('/','-')});}
function wbSharedKnowledgePage(){
 const folders=[['企业社会责任报告','已启用'],['党建','无资料'],['公益','无资料']];
 return `<div class="wb-shared-space"><aside><label>${icon('search')}<input id="wb-shared-query" placeholder="搜索共享资源"></label><strong>${icon('book')} CSR</strong>${folders.map(([name])=>`<button>${icon('folder')}${name}</button>`).join('')}</aside><main><div class="wb-shared-path">←　→　↑　↻　<span>共享资源　›　CSR</span><b>资料概览　•••</b></div><div class="wb-shared-filters"><select><option>全部类型</option></select><select><option>全部状态</option></select><select><option>全部核心标记</option></select><select><option>最近更新</option></select><input placeholder="搜索名称"></div><p>共 3 项</p><div class="wb-agent-table"><table><thead><tr><th>名称</th><th>权限</th><th>状态</th><th>核心标记</th><th>格式</th><th>可见范围</th><th>更新时间</th><th>操作</th></tr></thead><tbody>${folders.map(([name,status],i)=>`<tr><td><b class="wb-folder-name">${icon('folder')}${name}</b></td><td>可读</td><td><span class="${i?'wb-gray-pill':'wb-green-pill'}">${status}</span></td><td>${i?'无资料':'非核心'}</td><td>文件夹</td><td>全部公开</td><td>2026-10-29 ${i?'17:05':'17:11'}</td><td>•••</td></tr>`).join('')}</tbody></table></div></main></div>`;
}
function wbMemberMenu(member){if(member.identity==='所有者')return '—';return `<details class="wb-row-menu"><summary aria-label="成员操作">•••</summary><div><button data-r-action="wb-member-permission" data-id="${E(member.id)}">修改权限</button><button data-r-action="wb-member-toggle" data-id="${E(member.id)}">${member.status==='正常'?'停用':'启用'}</button><button data-r-action="wb-member-remove" data-id="${E(member.id)}">移出团队</button></div></details>`;}
function wbKnowledgeTeamPage(){
 const team=workspace.knowledgeTeam,tab=WB.knowledgeTeamTab,tabs=[['members','成员'],['invite','邀请链接'],['projects','项目'],['settings','设置'],['logs','操作日志']];
 let content='';
 if(tab==='members'){
  const query=WB.knowledgeMemberQuery.trim().toLowerCase(),members=team.members.filter(member=>(member.name+' '+member.id).toLowerCase().includes(query));
  content=`<div class="wb-team-toolbar"><label>${icon('search')}<input id="wb-member-query" placeholder="搜索成员" value="${E(WB.knowledgeMemberQuery)}"></label><button class="solid" data-r-action="wb-add-member">${icon('users')} 添加成员</button></div><div class="wb-agent-table wb-member-table"><table><thead><tr><th>成员</th><th>身份</th><th>权限</th><th>状态</th><th>操作</th></tr></thead><tbody>${members.map(member=>`<tr><td><b>${E(member.name)}</b><small>${E(member.id)}</small></td><td>${E(member.identity)}</td><td>${E(member.permission)}</td><td>${E(member.status)}</td><td>${wbMemberMenu(member)}</td></tr>`).join('')}</tbody></table></div><p class="wb-page-note">${members.length} 人</p>`;
 }else if(tab==='invite')content=`<div class="wb-invite-page"><div>${icon('users')} ${E(team.name)}</div><label>邀请权限<select id="wb-invite-page-permission"><option>可读</option><option>可编辑</option><option>可管理</option></select></label><p>${team.invites[0]?`当前邀请链接：<strong>${E(team.invites[0].url)}</strong>`:'尚未创建邀请链接。'}</p><button class="solid" data-r-action="wb-create-page-invite">🔗　创建邀请链接</button></div>`;
 else if(tab==='projects'){
  const query=WB.knowledgeProjectQuery.trim().toLowerCase(),projects=workspace.projects.filter(project=>(project.name||'').toLowerCase().includes(query));
  content=`<div class="wb-team-toolbar"><label>${icon('search')}<input id="wb-project-query" placeholder="搜索项目" value="${E(WB.knowledgeProjectQuery)}"></label><button data-r-action="wb-team-query">查询</button></div><div class="wb-agent-table"><table><thead><tr><th>项目</th><th>归属人</th><th>状态</th><th>操作</th></tr></thead><tbody>${projects.map(project=>`<tr><td>${E(project.name)}</td><td>张淼</td><td>启用</td><td>•••</td></tr>`).join('')||'<tr><td colspan="4" class="wb-table-empty">暂无项目</td></tr>'}</tbody></table></div><p class="wb-page-note">${projects.length} 个项目</p>`;
 }else if(tab==='settings')content=`<form id="wb-team-settings" class="wb-team-settings"><label><span><i>*</i> 团队名称</span><input name="name" required value="${E(team.name)}"></label><label><span>团队状态</span><select name="status"><option ${team.status==='启用'?'selected':''}>启用</option><option ${team.status==='停用'?'selected':''}>停用</option></select></label><hr><div><span>当前所有者</span><b>${E(team.owner.name)}</b><small>${E(team.owner.id)}</small></div><footer><button class="solid" type="submit">保存</button><button type="reset">重置</button></footer></form>`;
 else {const logs=team.logs.filter(log=>!WB.knowledgeLogQuery||log.action.includes(WB.knowledgeLogQuery));content=`<div class="wb-log-toolbar"><select id="wb-log-query"><option value="">全部操作</option>${[...new Set(team.logs.map(log=>log.action))].map(action=>`<option ${WB.knowledgeLogQuery===action?'selected':''}>${E(action)}</option>`).join('')}</select><label>◷ <input type="date">　-　<input type="date"></label><button data-r-action="wb-team-query">查询</button></div><div class="wb-agent-table"><table><thead><tr><th>操作</th><th>对象</th><th>操作者</th><th>时间</th><th>详情</th></tr></thead><tbody>${logs.map(log=>`<tr><td>${E(log.action)}</td><td>${E(log.target)}</td><td>${E(log.operator)}</td><td>${E(log.time)}</td><td><button>查看详情</button></td></tr>`).join('')}</tbody></table></div><p class="wb-page-note">${logs.length} 条</p>`;}
 return `<div class="wb-team-page"><header><button data-r-action="wb-team-back">← 返回知识库</button><h1>${E(team.name)}</h1><span>张</span></header><nav>${tabs.map(([id,label])=>awButton('wb-team-tab',label,id,tab===id?'active':'')).join('')}</nav><section>${content}</section></div>`;
}
function wbKnowledgePage(){
 if(WB.knowledgeView==='team')return wbKnowledgeTeamPage();
 let rows=workspace.knowledge.filter(k=>(WB.knowledgeTab==='shared'?k.sharedWithMe:!k.sharedWithMe)&&(k.name+' '+k.content).toLowerCase().includes(WB.knowledgeQuery.toLowerCase()));
 rows.sort(WB.knowledgeSort==='name'?(a,b)=>a.name.localeCompare(b.name,'zh-CN'):(a,b)=>(Date.parse(b.updated||b.created)||0)-(Date.parse(a.updated||a.created)||0));
 const documentMenu=k=>`<details class="wb-row-menu wb-knowledge-menu"><summary aria-label="${E(k.name)}更多操作">•••</summary><div><button data-r-action="wb-rename-knowledge" data-id="${E(k.id)}">重命名</button><button class="danger-text" data-r-action="wb-delete-knowledge" data-id="${E(k.id)}">删除</button></div></details>`;
 const folderMenu=folder=>`<details class="wb-row-menu wb-knowledge-menu"><summary aria-label="${E(folder.name)}更多操作">•••</summary><div><button data-r-action="wb-rename-knowledge-folder" data-id="${E(folder.id)}">重命名</button><button class="danger-text" data-r-action="wb-delete-knowledge-folder" data-id="${E(folder.id)}">删除</button></div></details>`;
 const knowledgeRow=k=>`<div class="wb-knowledge-document-row"><button type="button" data-r-action="wb-edit-knowledge" data-id="${E(k.id)}">${icon('book')}<span>${E(k.name)}</span></button>${documentMenu(k)}</div>`;
 const selectedFolder=workspace.knowledgeFolders.find(folder=>folder.id===WB.knowledgeFolderId);
 const folderView=selectedFolder?(()=>{const items=rows.filter(item=>item.folderId===selectedFolder.id);return `<section class="wb-knowledge-folder-view"><header><button class="wb-knowledge-back" data-r-action="wb-close-knowledge-folder">← 返回</button><div>${icon('folder')}<span><h2>${E(selectedFolder.name)}</h2><small>${items.length} 个文档</small></span></div><nav><button class="solid" data-r-action="wb-new-knowledge" data-owner="${E(selectedFolder.id)}">＋ 上传知识</button>${folderMenu(selectedFolder)}</nav></header><div class="wb-knowledge-document-cards">${items.map(k=>`<article><button type="button" data-r-action="wb-edit-knowledge" data-id="${E(k.id)}">${icon('book')}<span><h3>${E(k.name)}</h3><small>${E(k.files?.[0]?.name||'知识文档')}</small></span></button>${documentMenu(k)}</article>`).join('')||'<p class="wb-knowledge-folder-empty">这个文件夹还没有文档，点击“上传知识”添加文件。</p>'}</div></section>`;})():'';
 const listFolders=workspace.knowledgeFolders.map(folder=>{const items=rows.filter(item=>item.folderId===folder.id);return `<section class="wb-knowledge-folder"><header><button class="wb-knowledge-folder-title" data-r-action="wb-open-knowledge-folder" data-id="${E(folder.id)}">${icon('folder')}<span><h2>${E(folder.name)}</h2><small>${items.length} 个文档</small></span></button><nav><button class="solid" data-r-action="wb-new-knowledge" data-owner="${E(folder.id)}">＋ 上传知识</button>${folderMenu(folder)}</nav></header><div class="wb-knowledge-document-list">${items.map(knowledgeRow).join('')||'<p class="wb-knowledge-folder-empty">这个文件夹还没有文档，点击“上传知识”添加文件。</p>'}</div></section>`;}).join('');
 const gridFolders=`<div class="wb-knowledge-folder-grid">${workspace.knowledgeFolders.map(folder=>{const items=rows.filter(item=>item.folderId===folder.id);return `<article><button type="button" class="wb-knowledge-folder-card" data-r-action="wb-open-knowledge-folder" data-id="${E(folder.id)}">${icon('folder')}<span><h2>${E(folder.name)}</h2><small>${items.length} 个文档</small></span></button>${folderMenu(folder)}</article>`;}).join('')||wbAgentEmpty('暂无一级文件夹')}</div>`;
 const library=selectedFolder?folderView:WB.knowledgeLayout==='grid'?gridFolders:`<div class="wb-knowledge-folders">${listFolders||wbAgentEmpty('暂无一级文件夹')}</div>`;
 return `<header class="wb-knowledge-head"><div class="wb-inner-tabs">${[['team','团队'],['shared','与我共享']].map(([id,label])=>awButton('wb-knowledge-tab',label,id,WB.knowledgeTab===id?'active':'')).join('')}</div><select aria-label="知识库工作空间"><option>${E(workspace.knowledgeTeam.name)}</option></select><button class="wb-team-entry" data-r-action="wb-open-team" aria-label="管理团队成员" title="管理团队成员">${icon('users')}</button><span class="wb-knowledge-label">知识库</span></header>${WB.knowledgeTab==='shared'?wbSharedKnowledgePage():`<div class="wb-agent-page-body"><div class="wb-agent-toolbar"><input id="wb-knowledge-query" aria-label="搜索知识" placeholder="搜索知识" value="${E(WB.knowledgeQuery)}"><button data-r-action="wb-knowledge-query">查询</button><select class="wb-push-right" id="wb-knowledge-sort" aria-label="知识排序"><option value="recent">最近更新</option><option value="name" ${WB.knowledgeSort==='name'?'selected':''}>名称排序</option></select><div class="wb-layout-buttons">${[['list','☷','列表视图'],['grid','▦','网格视图']].map(([id,glyph,label])=>`<button data-r-action="wb-knowledge-layout" data-id="${id}" class="${WB.knowledgeLayout===id?'active':''}" aria-label="${label}">${glyph}</button>`).join('')}</div>${selectedFolder?'':`<button class="solid" data-r-action="wb-new-knowledge-folder">＋ 新建一级文件夹</button>`}</div>${library}</div>`}`;
}
const wbMemberDialog=document.createElement('dialog');wbMemberDialog.id='wb-member-dialog';wbMemberDialog.setAttribute('aria-label','添加成员');document.body.append(wbMemberDialog);
function wbDrawMemberDialog(mode='invite'){
 const team=workspace.knowledgeTeam,permission=WB.memberPermission||'可读',invite=team.invites[0];
 wbMemberDialog.innerHTML=`<form id="wb-member-form"><header><h2>添加成员</h2><button type="button" data-r-action="wb-close-member" aria-label="关闭">×</button></header><nav>${[['invite','邀请链接'],['specific','指定用户']].map(([id,label])=>awButton('wb-member-mode',label,id,mode===id?'active':'')).join('')}</nav><main>${mode==='invite'?`<div class="wb-team-name">${icon('users')} ${E(team.name)}</div><label>邀请权限<select name="permission"><option ${permission==='可读'?'selected':''}>可读</option><option ${permission==='可编辑'?'selected':''}>可编辑</option><option ${permission==='可管理'?'selected':''}>可管理</option></select></label><p>${invite?`邀请链接已创建：<strong>${E(invite.url)}</strong>`:'尚未创建邀请链接。'}</p><button type="submit" class="solid">🔗　${invite?'重新创建邀请链接':'创建邀请链接'}</button>`:`<label><span><i>*</i> 成员</span><input name="member" required placeholder="搜索姓名或用户 ID"></label><label>权限<select name="permission"><option>可读</option><option>可编辑</option><option>可管理</option></select></label>`}</main><footer><button type="button" data-r-action="wb-close-member">取消</button>${mode==='specific'?'<button class="solid" type="submit">添加成员</button>':''}</footer></form>`;
 const form=$('#wb-member-form');form.elements.permission.onchange=event=>WB.memberPermission=event.target.value;form.onsubmit=event=>{event.preventDefault();const data=Object.fromEntries(new FormData(form));if(mode==='invite'){const code=Math.random().toString(36).slice(2,10);team.invites=[{url:`https://invite.example/${code}`,permission:data.permission}];wbTeamLog('创建邀请链接',`权限 · ${data.permission}`);persist();wbDrawMemberDialog('invite');toast('邀请链接已创建');}else{const value=data.member.trim();team.members.push({id:String(Date.now()),name:value,identity:'成员',permission:data.permission,status:'正常'});wbTeamLog('添加团队成员',value);persist();wbMemberDialog.close();wbRenderAgentPage();toast(`已添加成员「${value}」`);}};
}

const wbSkillCategories=['全部','广告投放','数据报表','内容创作','知识与工具'];
function wbSkillCategory(skill){const text=`${skill.name||''} ${skill.description||''} ${skill.id||''}`,id=skill.id||'',category=skill.category||'';if(category==='发布'||/normal-plan|batch-publish|xingguang|asset-library-selector/.test(id))return '广告投放';if(category==='报表'||/account-analysis|wide-table|report-tool|market-data|gap-analysis|settlement-import|meta-ai-diagnosis/.test(id))return '数据报表';if(category==='知识库资源'||/knowledge-logo|content-attribution|reference-material/.test(id))return '内容创作';if(/发布|投放|广告|星广|达人|回传|流量包/.test(text))return '广告投放';if(/内容|素材|视频|脚本|创意|设计|文案|Logo|品牌/.test(text))return '内容创作';if(/报表|数据查询|宽表|获客|市场数据|结算|账户分析|缺口分析/.test(text))return '数据报表';return '知识与工具';}
const wbDemoSkill={id:'wb-media-crawler',name:'爬虫skill',description:'小红书、抖音、微博和快手社交媒体内容采集与同步的 Wefly 媒体爬虫 API 工作流程。',category:'内容创作',status:'已发布',updated:'2026/10/29 14:49',files:{'SKILL.md':'---\nname: 爬虫skill\ndescription: 社交媒体内容采集与同步工作流\n---\n\n# 爬虫skill\n\n用于小红书、抖音、微博和快手的内容采集、关键词搜索与主页评论同步。\n','references/ai-material-query.md':'# AI 素材查询\n\n根据关键词、平台和时间范围查询素材。\n','references/api-overview.md':'# API 概览\n\n说明接口鉴权、请求参数和响应结构。\n','references/homepage-comments.md':'# 主页评论采集\n\n采集指定主页的公开评论。\n','references/real-time-crawler.md':'# 实时采集\n\n按任务查询实时采集进度。\n','references/response-envelope.md':'# 响应结构\n\n统一返回状态、数据与错误信息。\n','references/search-keyword.md':'# 关键词搜索\n\n按平台搜索公开内容。\n','references/search-topic.md':'# 话题搜索\n\n按话题检索趋势内容。\n'}};
