function wbSharedSkills(){const catalog=R.catalog?.skills||window.AssistantScenarios?.skills||[];const published=R.data.skills.filter(skill=>skill.published);const fallback=[{id:'shared-bilibili',name:'B站热榜查询',description:'查询并整理哔哩哔哩热门排行榜数据，按用户要求返回原始数据或结构化榜单。',author:'阮陈贵',updated:'2026/10/15 15:10:46'},{id:'shared-acceptance',name:'广告操作到期效果验收',description:'读取广告操作验收队列，查询到期操作的前后效果并生成中文验收日报。',author:'伍迪航',updated:'2026/9/24 17:21:09'},{id:'shared-batch',name:'AA星广多任务ID修改与批量发布',description:'将模板广告组或计划批量复制到目标账户，并替换星广任务 ID 与批量参数。',author:'伍迪航',updated:'2026/9/23 15:27:13'},{id:'shared-confirm',name:'广告操作拉取与人工确认',description:'拉取指定产品和渠道的新增广告操作，并写入人工确认队列。',author:'伍迪航',updated:'2026/9/22 19:42:15'}];return [...published,...catalog,...fallback].filter((skill,index,rows)=>rows.findIndex(item=>item.id===skill.id)===index);}
function wbSkillsPage(){
 if(WB.skillTab==='mine')wbEnsureMySkills();
 const source=WB.skillTab==='mine'?R.data.skills:wbSharedSkills(),query=WB.skillQuery.trim().toLowerCase(),matched=source.filter(skill=>(`${skill.name||''} ${skill.description||''} ${skill.author||''}`).toLowerCase().includes(query));
 const mineRow=skill=>`<article class="wb-skill-row"><div><h3>${E(skill.name)}</h3><p>${E(skill.description||'个人技能')}</p><small>${E(skill.status||'未发布')}${skill.updated?' · '+E(skill.updated):''}</small></div><nav><button data-r-action="wb-skill-edit" data-id="${E(skill.id)}">编辑</button><button class="solid" data-r-action="wb-skill-publish" data-id="${E(skill.id)}">发布共享技能</button><button class="danger" data-r-action="wb-skill-delete" data-id="${E(skill.id)}">删除</button></nav></article>`;
 const sharedRow=skill=>`<article class="wb-skill-row"><div><h3>${E(skill.name)}</h3><p>${E(skill.description||'共享技能')}</p><small>${E(skill.author||'平台团队')} · 租户 ${E(skill.tenant||'fly')} · 跨租户共享技能${skill.updated?' · '+E(skill.updated):''}</small></div><nav><button data-r-action="wb-shared-skill-view" data-id="${E(skill.id)}">查看</button><button class="wb-skill-push" data-r-action="wb-skill-force-push" data-id="${E(skill.id)}">强制推送</button></nav></article>`;
 const counts=Object.fromEntries(wbSkillCategories.map(category=>[category,category==='全部'?matched.length:matched.filter(skill=>wbSkillCategory(skill)===category).length]));
 const categories=WB.skillCategory==='全部'?wbSkillCategories.slice(1):[WB.skillCategory],groups=categories.map(category=>{const rows=matched.filter(skill=>wbSkillCategory(skill)===category);return rows.length?`<section class="wb-skill-category-group"><header><div><h2>${E(category)}</h2><p>${category==='广告投放'?'投放执行、账户优化与批量发布':category==='数据报表'?'数据查询、归因分析与复盘报告':category==='内容创作'?'内容采集、脚本创作与素材生产':'知识检索、协作与通用工作工具'}</p></div><span>${rows.length} 个技能</span></header><div class="wb-skill-list shared">${rows.map(sharedRow).join('')}</div></section>`:'';}).join('');
 const body=WB.skillTab==='mine'?`<div class="wb-skill-list mine">${matched.map(mineRow).join('')||wbAgentEmpty('暂无匹配的技能')}</div>`:`<nav class="wb-skill-categories wb-skill-primary-categories" aria-label="共享技能一级分类">${wbSkillCategories.map(category=>`<button class="${WB.skillCategory===category?'active':''}" data-r-action="wb-skill-category" data-id="${E(category)}"><span>${E(category)}</span><small>${counts[category]}</small></button>`).join('')}</nav>${groups||wbAgentEmpty('当前分类暂无匹配的技能')}`;
 return wbPageHead('技能管理')+`<div class="wb-skills-body"><p class="wb-page-note">个人技能可在聊天和自动化中使用；共享技能按一级分类查找并下载后使用。</p><div class="wb-agent-toolbar wb-skill-toolbar"><div class="wb-inner-tabs">${[['mine','我的技能'],['shared','共享技能']].map(([id,label])=>awButton('wb-skill-tab',label,id,WB.skillTab===id?'active':'')).join('')}</div><label class="wb-skill-search">${icon('search')}<input id="wb-skill-query" aria-label="搜索技能名称、描述或发布者" placeholder="搜索名称、描述或发布者" value="${E(WB.skillQuery)}"></label>${WB.skillTab==='mine'?'<button class="solid wb-skill-import" data-r-action="import-skill">⇩ 导入 ZIP</button><input hidden id="skill-file-input" type="file" accept=".zip,application/zip">':''}</div>${body}</div>`;
}
const wbSkillEditorDialog=document.createElement('dialog');wbSkillEditorDialog.id='wb-skill-editor-dialog';wbSkillEditorDialog.setAttribute('aria-label','编辑技能');document.body.append(wbSkillEditorDialog);
const wbSkillPublishDialog=document.createElement('dialog');wbSkillPublishDialog.id='wb-skill-publish-dialog';wbSkillPublishDialog.setAttribute('aria-label','发布共享技能');document.body.append(wbSkillPublishDialog);
function wbSkillById(id){return R.data.skills.find(skill=>skill.id===id)||wbSharedSkills().find(skill=>skill.id===id);}
function wbSkillTree(files,active){const keys=Object.keys(files||{}),root=keys.filter(file=>!file.includes('/')),groups=new Map;for(const file of keys.filter(file=>file.includes('/'))){const [folder]=file.split('/');if(!groups.has(folder))groups.set(folder,[]);groups.get(folder).push(file);}return `${[...groups].map(([folder,items])=>`<section><b>⌄　▭ ${E(folder)}</b>${items.map(file=>`<button type="button" class="${file===active?'active':''}" data-r-action="wb-skill-file" data-id="${E(file)}">▧ ${E(file.split('/').pop())}</button>`).join('')}</section>`).join('')}${root.map(file=>`<button type="button" class="${file===active?'active':''}" data-r-action="wb-skill-file" data-id="${E(file)}">▧ ${E(file)}</button>`).join('')}`;}
function wbDrawSkillEditor(id,editable=true){const original=wbSkillById(id);if(!original)return;WB.skillEditingId=id;WB.skillEditorDraft=structuredClone(original);WB.skillEditorSnapshot=structuredClone(original);WB.skillEditorFile=Object.keys(WB.skillEditorDraft.files||{})[0]||'SKILL.md';WB.skillEditorDraft.files??={'SKILL.md':''};wbRenderSkillEditor(editable);if(!wbSkillEditorDialog.open)wbSkillEditorDialog.showModal();}
function wbRenderSkillEditor(editable=true){const skill=WB.skillEditorDraft,file=WB.skillEditorFile;wbSkillEditorDialog.innerHTML=`<div class="wb-skill-editor-shell"><header><button data-r-action="wb-close-skill-editor">← 返回技能列表</button><h2>${editable?'编辑技能':'查看技能'} · ${E(skill.name)}</h2><nav>${editable?'<button class="solid" data-r-action="wb-skill-editor-save">▣ 保存</button><button data-r-action="wb-skill-editor-reset">↶ 重置（还原）</button><button class="danger" data-r-action="wb-skill-editor-delete">♜ 删除</button>':'<button data-r-action="wb-close-skill-editor">关闭</button>'}</nav></header><main><aside><h3>我的技能</h3>${R.data.skills.map(item=>`<button class="${item.id===skill.id?'active':''}" data-r-action="wb-skill-edit" data-id="${E(item.id)}"><b>${E(item.name)}</b><small>${E(item.description||'个人技能')}</small><em>${E(item.status||'未发布')}</em></button>`).join('')}</aside><section class="wb-skill-tree"><h3>Skill 目录</h3>${wbSkillTree(skill.files,file)}</section><label class="wb-skill-code"><span>${E(file)}</span><textarea id="wb-skill-editor-content" spellcheck="false" ${editable?'':'readonly'}>${E(skill.files[file]||'')}</textarea></label></main></div>`;}
function wbSyncSkillEditor(){const input=$('#wb-skill-editor-content');if(input&&WB.skillEditorDraft?.files)WB.skillEditorDraft.files[WB.skillEditorFile]=input.value;}
function wbDrawSkillPublish(id,query=''){const skill=wbSkillById(id);if(!skill)return;WB.skillPublishingId=id;WB.skillPublishMembers??=new Set(skill.sharedWith||[]);const members=workspace.collaborationMembers.filter(name=>name.toLowerCase().includes(query.trim().toLowerCase()));wbSkillPublishDialog.innerHTML=`<form id="wb-skill-publish-form"><header><h2>发布共享技能</h2><button type="button" data-r-action="wb-close-skill-publish">×</button></header><main><p><b>${E(skill.name)}</b> · 选择可查看和下载的用户。不选择人员时仅自己可见。</p><label class="wb-publish-search"><input id="wb-skill-member-query" placeholder="输入姓名或用户 ID 搜索" value="${E(query)}"><button type="button">搜索</button></label><small>输入关键词后搜索当前租户用户。</small><div>${members.map(name=>`<label><input type="checkbox" value="${E(name)}" ${WB.skillPublishMembers.has(name)?'checked':''}><span>${E(name.slice(0,1))}</span><b>${E(name)}</b></label>`).join('')||'<p>没有匹配的成员</p>'}</div></main><footer><button type="button" data-r-action="wb-close-skill-publish">取消</button><button type="submit" class="solid">确认发布</button></footer></form>`;const form=$('#wb-skill-publish-form'),input=$('#wb-skill-member-query');input.oninput=e=>{form.querySelectorAll('main>div input').forEach(item=>item.checked?WB.skillPublishMembers.add(item.value):WB.skillPublishMembers.delete(item.value));const pos=e.target.selectionStart;wbDrawSkillPublish(id,e.target.value);$('#wb-skill-member-query').focus();$('#wb-skill-member-query').setSelectionRange(pos,pos);};form.onsubmit=e=>{e.preventDefault();form.querySelectorAll('main>div input').forEach(item=>item.checked?WB.skillPublishMembers.add(item.value):WB.skillPublishMembers.delete(item.value));skill.published=true;skill.status='已发布';skill.sharedWith=[...WB.skillPublishMembers];skill.updated=now();persist();wbSkillPublishDialog.close();wbRenderAgentPage();toast(`「${skill.name}」已发布为共享技能`);};}
