const wbExpertCategories=['全部','我的专家','内容创作','广告投放','品牌公关'];
workspace.expertSettings??={};workspace.hiddenExpertIds??=[];workspace.pinnedExpertIds??=[];workspace.usedExpertIds??=[...new Set((workspace.projects||[]).flatMap(project=>(project.chats||[]).map(chat=>chat.expert?.id).filter(Boolean)))];
function wbExpertCategory(expert){if(wbExpertCategories.includes(expert.category))return expert.category;if(/品牌|公关|舆情|审核|合规/.test(`${expert.name} ${expert.category} ${(expert.tags||[]).join(' ')}`))return '品牌公关';if(/内容|设计|编导|视频|直播|社媒|制片|游戏|新媒体/.test(`${expert.name} ${expert.category} ${(expert.tags||[]).join(' ')}`))return '内容创作';return '广告投放';}
function wbExpertView(expert){const settings=workspace.expertSettings[expert.id]||{};return {...expert,name:settings.name||expert.name,category:wbExpertCategory(expert),knowledgeIds:settings.knowledgeIds||expert.knowledgeIds||[],pinned:workspace.pinnedExpertIds.includes(expert.id)};}
function wbVisibleExpert(expert){return !workspace.hiddenExpertIds.includes(expert.id);}
function wbAllExperts(){return [...wbCoreExperts,...workspace.experts,...wbPresetExperts].filter(wbVisibleExpert).map(wbExpertView);}
function wbSidebarExperts(){return [...wbCoreExperts,...workspace.experts.filter(expert=>workspace.usedExpertIds.includes(expert.id)),...wbPresetExperts.filter(expert=>workspace.usedExpertIds.includes(expert.id))].filter((expert,index,rows)=>rows.findIndex(item=>item.id===expert.id)===index).filter(wbVisibleExpert).map(wbExpertView).sort((a,b)=>Number(b.pinned)-Number(a.pinned));}
function wbFindExpert(id){const expert=[...wbCoreExperts,...workspace.experts,...wbPresetExperts].find(item=>item.id===id);return expert&&wbVisibleExpert(expert)?wbExpertView(expert):null;}
function wbMostRecentExpert(){const conversation=(workspace.projects||[]).flatMap(project=>project.chats||[]).filter(item=>item.expert?.id).sort((a,b)=>(b.updated||b.created||0)-(a.updated||a.created||0))[0];return conversation?wbFindExpert(conversation.expert.id):null;}
function wbApplyConversationExpert(conversation,expert,applyCapabilities=false){if(!conversation||!expert)return;conversation.expert={id:expert.id,name:expert.name,avatar:expert.avatar,instruction:wbExpertInstruction(expert),mcps:expert.mcps||[]};workspace.lastSelectedExpertId=expert.id;if(!expert.system&&!workspace.usedExpertIds.includes(expert.id))workspace.usedExpertIds.push(expert.id);if(applyCapabilities){conversation.knowledge=expert.knowledgeIds?.length?expert.knowledgeIds.filter(id=>workspace.knowledge.some(item=>item.id===id)||wbBuiltinKnowledge.some(item=>item.id===id)):null;conversation.skillIds=[...(expert.skillIds||[])];}}
function wbIncomingTransfer(conversation=awChat()){return conversation?.collaboration?.tasks?.find(task=>task.mode==='transfer'&&task.status==='pending'&&task.assignee==='张淼');}
function wbRenderComposerAgent(){const composer=$('#composer');if(!composer)return;let host=$('#wb-composer-agent');if(!host){host=document.createElement('div');host.id='wb-composer-agent';composer.after(host);}const visible=WB.agentSection==='chat'&&!AW.folder&&assistantShell.dataset.presentation==='page';host.hidden=!visible;if(!visible)return;const conversation=awChat(),incoming=wbIncomingTransfer(conversation),prompt=$('#prompt'),send=$('#send');if(incoming){host.innerHTML='';host.hidden=true;if(prompt){prompt.disabled=true;prompt.placeholder='请先在会话消息中接受转接';}if(send)send.disabled=true;return;}host.hidden=false;if(prompt){prompt.disabled=false;prompt.placeholder='给 Wefly 发送消息，@ 引用策略预设';}const expert=wbFindExpert(conversation.expert?.id)||wbFindExpert(workspace.lastSelectedExpertId)||wbMostRecentExpert()||wbFindExpert('core-default');if(!expert)return;if(!conversation.expert){wbApplyConversationExpert(conversation,expert,false);conversation.skillIds=[];persist();}if(send)send.disabled=!conversation.draft?.trim()||AW.uploading;host.innerHTML=`<details><summary aria-label="切换 Agent"><span class="wb-composer-agent-avatar">${wbExpertAvatarMarkup(expert.avatar,expert.name.slice(0,1))}</span><b>${E(expert.name)}</b><i>⌄</i></summary><div class="wb-composer-agent-popover"><small>AGENT</small><button type="button" class="wb-composer-agent-new" data-r-action="wb-new-expert" aria-label="新建 Agent">＋ <span>新建 Agent</span></button>${wbAllExperts().map(item=>`<button type="button" class="wb-composer-agent-option ${item.id===expert.id?'active':''}" data-r-action="wb-composer-expert" data-id="${E(item.id)}" aria-label="选择 ${E(item.name)}"><span>${wbExpertAvatarMarkup(item.avatar,item.name.slice(0,1))}</span><b>${E(item.name)}</b>${item.id===expert.id?'<i>✓</i>':''}</button>`).join('')}</div></details>`;}
