 const menu=expert=>expert.custom?`<details class="wb-expert-card-menu"><summary aria-label="${E(expert.name)}更多操作">•••</summary><div><button data-r-action="wb-expert-detail" data-id="${E(expert.id)}">◉　查看专家</button><button data-r-action="wb-edit-expert" data-id="${E(expert.id)}">✎　修改专家</button><button data-r-action="wb-share-expert" data-id="${E(expert.id)}">↗　分享</button><button data-r-action="wb-open-expert-folder" data-id="${E(expert.id)}">□　打开文件夹</button><button class="danger-text" data-r-action="wb-delete-expert" data-id="${E(expert.id)}">♲　删除</button></div></details>`:'';
