function wbExpertAvatarMarkup(avatar,fallback='AI'){const value=String(avatar||'');return value.startsWith('data:image/')?`<img src="${E(value)}" alt="">`:E(value||fallback);}
function wbReadExpertAvatar(file){return new Promise((resolve,reject)=>{if(!file||!file.type.startsWith('image/'))return reject(new Error('请选择图片文件'));if(file.size>10*1024*1024)return reject(new Error('图片不能超过 10MB'));const reader=new FileReader();reader.onerror=()=>reject(new Error('图片读取失败'));reader.onload=()=>{const image=new Image();image.onerror=()=>reject(new Error('无法识别这张图片'));image.onload=()=>{const size=256,canvas=document.createElement('canvas'),context=canvas.getContext('2d'),scale=Math.max(size/image.width,size/image.height),width=image.width*scale,height=image.height*scale;canvas.width=size;canvas.height=size;context.drawImage(image,(size-width)/2,(size-height)/2,width,height);resolve(canvas.toDataURL('image/webp',.88));};image.src=reader.result;};reader.readAsDataURL(file);});}
const wbBuiltinKnowledge=[
 {id:'expert-k-brand',name:'TT语音品牌规范',folder:'品牌与产品',subfolder:'品牌资料',content:'品牌定位、语气、视觉与使用边界'},
 {id:'expert-k-product',name:'核心功能与用户画像',folder:'品牌与产品',subfolder:'产品资料',content:'产品功能、目标受众和关键使用场景'},
 {id:'expert-k-script',name:'短视频脚本方法',folder:'内容与运营',subfolder:'内容方法',content:'开头钩子、结构节奏、对白与收口方法'},
 {id:'expert-k-review',name:'投放复盘规范',folder:'内容与运营',subfolder:'复盘资料',content:'素材表现、转化信号与复盘口径'}
];
function wbKnowledgeRows(){const rows=(workspace.knowledge||[]).filter(item=>!item.disabled).map(item=>{const product=/品牌|产品|用户|画像/.test(item.name),method=/方法|脚本|内容|创意/.test(item.name),folder=workspace.knowledgeFolders?.find(entry=>entry.id===item.folderId)?.name;return {...item,folder:folder||(product?'品牌与产品':'内容与运营'),subfolder:item.subfolder||(product?'项目资料':method?'内容方法':'复盘资料')};});return rows.length?rows:wbBuiltinKnowledge;}
function wbKnowledgeTree(){const tree=new Map;for(const item of wbKnowledgeRows()){if(!tree.has(item.folder))tree.set(item.folder,new Map);const folder=tree.get(item.folder);if(!folder.has(item.subfolder))folder.set(item.subfolder,[]);folder.get(item.subfolder).push(item);}return tree;}
function wbRenderSelectedKnowledge(){const host=$('#wb-expert-selected-knowledge');if(!host)return;const selected=new Set(WB.expertDraftKnowledge||[]),rows=wbKnowledgeRows().filter(item=>selected.has(item.id));host.innerHTML=rows.length?`<div>${rows.slice(0,4).map(item=>`<span>${icon('book')}${E(item.name)}</span>`).join('')}${rows.length>4?`<small>另有 ${rows.length-4} 条</small>`:''}</div><b>已选择 ${rows.length} 条知识</b>`:'<p>尚未添加知识，可按文件夹或单条知识选择</p>';}
function wbSyncKnowledgeChecks(){const form=$('#wb-expert-knowledge-form');if(!form)return;for(const section of form.querySelectorAll('[data-knowledge-subfolder]')){const parent=section.querySelector('[data-knowledge-subfolder-check]'),children=[...section.querySelectorAll('[name=knowledge]')],checked=children.filter(item=>item.checked).length;parent.checked=checked===children.length&&children.length>0;parent.indeterminate=checked>0&&checked<children.length;}for(const details of form.querySelectorAll('[data-knowledge-folder]')){const parent=details.querySelector('[data-knowledge-folder-check]'),children=[...details.querySelectorAll('[name=knowledge]')],checked=children.filter(item=>item.checked).length;parent.checked=checked===children.length&&children.length>0;parent.indeterminate=checked>0&&checked<children.length;}}
function wbDrawKnowledgeDialog(){const selected=new Set(WB.expertDraftKnowledge||[]),tree=wbKnowledgeTree();wbExpertKnowledgeDialog.innerHTML=`<form id="wb-expert-knowledge-form"><header><div><small>KNOWLEDGE</small><h2>添加知识</h2><p>可选择一级文件夹、二级文件夹，或其中一条具体知识。</p></div><button type="button" data-r-action="wb-close-expert-knowledge" aria-label="关闭">×</button></header><main>${[...tree].map(([folder,subfolders])=>{const count=[...subfolders.values()].flat().length;return `<details open data-knowledge-folder><summary><input type="checkbox" data-knowledge-folder-check> ${E(folder)}<small>${count} 条知识</small></summary>${[...subfolders].map(([subfolder,items])=>`<section data-knowledge-subfolder><h3><label><input type="checkbox" data-knowledge-subfolder-check><span><b>${E(subfolder)}</b><small>选择该文件夹下全部知识</small></span></label></h3>${items.map(item=>`<label><input type="checkbox" name="knowledge" value="${E(item.id)}" ${selected.has(item.id)?'checked':''}><span><b>${icon('book')}${E(item.name)}</b></span></label>`).join('')}</section>`).join('')}</details>`;}).join('')}</main><footer><button type="button" data-r-action="wb-close-expert-knowledge">取消</button><button type="submit" class="solid">确认添加</button></footer></form>`;const form=$('#wb-expert-knowledge-form');form.querySelectorAll('[data-knowledge-folder-check]').forEach(input=>input.onchange=event=>{event.target.closest('details').querySelectorAll('[name=knowledge]').forEach(item=>item.checked=event.target.checked);wbSyncKnowledgeChecks();});form.querySelectorAll('[data-knowledge-subfolder-check]').forEach(input=>input.onchange=event=>{event.target.closest('section').querySelectorAll('[name=knowledge]').forEach(item=>item.checked=event.target.checked);wbSyncKnowledgeChecks();});form.querySelectorAll('[name=knowledge]').forEach(input=>input.onchange=wbSyncKnowledgeChecks);form.onsubmit=event=>{event.preventDefault();WB.expertDraftKnowledge=[...form.querySelectorAll('[name=knowledge]:checked')].map(item=>item.value);wbExpertKnowledgeDialog.close();wbRenderSelectedKnowledge();};wbSyncKnowledgeChecks();}
function wbExpertInstruction(expert){return expert.instruction||`你是${expert.name}。先确认用户的目标、资料范围与交付标准，再结合${(expert.tags||['专业经验']).join('、')}给出清晰、可执行、可核验的建议；涉及执行动作时先说明影响并等待用户确认。`;}
