function wbShowExpertSwitchNotice(name){const main=assistantShell.querySelector('.aw-main');if(!main)return;main.querySelector('.wb-expert-switch-notice')?.remove();const notice=document.createElement('div');notice.className='wb-expert-switch-notice';notice.textContent=`已切换至${/(专家|Agent|助手)$/.test(name)?name:name+'专家'}`;main.append(notice);requestAnimationFrame(()=>notice.classList.add('show'));clearTimeout(WB.expertNoticeTimer);WB.expertNoticeTimer=setTimeout(()=>{notice.classList.remove('show');setTimeout(()=>notice.remove(),180);},1800);}
function wbEnsureExpertInbox(expert){if(!expert)return null;if(!workspace.usedExpertIds.includes(expert.id))workspace.usedExpertIds.push(expert.id);let project=workspace.projects.find(item=>item.expertId===expert.id&&item.expertAuto);if(!project){project={version:1,id:uid(),name:expert.name,expertId:expert.id,expertAuto:true,brand:'',goal:'',audience:'',channels:'',voice:'',sources:[],insights:[],plans:[],drafts:[],rules:[],messages:[],history:[],chats:[],bindings:{knowledge:[],connectors:[]}};workspace.projects.unshift(project);}return project;}
function wbActivateExpert(expert,projectId=state.id,title=''){if(!expert)return;WB.expertMenuOpen=false;if(!workspace.usedExpertIds.includes(expert.id))workspace.usedExpertIds.push(expert.id);const targetProject=workspace.projects.find(item=>item.id===projectId),reuseEmptyProject=targetProject&&!targetProject.chats?.length;if(reuseEmptyProject){if(state.id!==projectId)switchProject(projectId);else ensureProject();}else awNewChat(projectId);const conversation=awChat();conversation.title=title||`${expert.name} · 专家协作`;conversation.updated=Date.now();wbApplyConversationExpert(conversation,expert,false);conversation.skillIds=[];state.messages=conversation.messages;workspace.adAgentTree??={experts:{},projects:{}};workspace.adAgentTree.experts??={};workspace.adAgentTree.projects??={};workspace.adAgentTree.experts[expert.id]=true;workspace.adAgentTree.projects[state.id]=true;WB.agentSection='chat';AW.tipsOpen=false;persist();renderAssistant();wbShowExpertSwitchNotice(expert.name);const prompt=$('#prompt');if(prompt){prompt.placeholder='给 Wefly 发送消息，@ 引用策略预设';prompt.focus();}}
function wbActivateMarketExpert(expert){const project=wbEnsureExpertInbox(expert);if(project)wbActivateExpert(expert,project.id,`与${expert.name}的对话`);}
function wbOpenExpertHistory(expert){if(!expert)return;const rows=workspace.projects.filter(project=>project.expertId===expert.id).flatMap(project=>(project.chats||[]).filter(conversation=>!conversation.archived).map(conversation=>({project,conversation}))).sort((a,b)=>(b.conversation.updated||b.conversation.created||0)-(a.conversation.updated||a.conversation.created||0));if(!rows.length)return wbActivateMarketExpert(expert);const {project,conversation}=rows[0];if(state.id!==project.id)switchProject(project.id);state.chatId=conversation.id;state.messages=conversation.messages;WB.agentSection='chat';AW.folder=null;assistantTab='chat';persist();renderAssistant();const prompt=$('#prompt');if(prompt){prompt.placeholder='给 Wefly 发送消息，@ 引用策略预设';prompt.focus();}}
