R.invoke('wb-move-expert-chat',button=>{const source=workspace.projects.find(item=>item.id===button.dataset.owner),conversation=source?.chats?.find(item=>item.id===button.dataset.id);if(!source||!conversation)return;const targets=workspace.projects.filter(project=>project.expertId===source.expertId&&project.id!==source.id),labels=targets.map(project=>project.expertAuto?'直属会话':project.name);if(!targets.length)return toast('请先在该 Agent 下新建文件夹');modal('移动对话',`将“${conversation.title}”移动到同一 Agent 的指定文件夹。`,[{key:'folder',label:'目标文件夹',options:labels,value:labels[0]}],values=>{const target=targets[labels.indexOf(values.folder)];if(!target)return;source.chats=source.chats.filter(item=>item.id!==conversation.id);target.chats??=[];target.chats.unshift(conversation);conversation.updated=Date.now();if(state.id===source.id&&state.chatId===conversation.id){if(state.id!==target.id)switchProject(target.id);state.chatId=conversation.id;state.messages=conversation.messages;}renderAssistant();toast(`已移动到「${values.folder}」`);});$('#save').textContent='移动';});
