function wbConfirmDeleteExpert(id){const expert=wbFindExpert(id);if(!expert)return;if(!expert.custom){toast('内置 Agent 与专家市场成员不支持删除');return;}const conversations=workspace.projects.reduce((total,project)=>total+(project.chats||[]).filter(item=>item.expert?.id===id).length,0);wbExpertDeleteDialog.innerHTML=`<form id="wb-expert-delete-form"><header><h2>确定是否删除当前 Agent？</h2><button type="button" data-r-action="wb-close-expert-delete" aria-label="关闭">×</button></header><div class="wb-delete-warning"><b>请谨慎确认以下删除影响，所有数据一旦删除均无法找回：</b><ul><li>当前 Agent 正在进行的所有对话都会终止</li><li>Agent 将无法再通过任何方式进行对话</li><li>${conversations} 段专属对话及其中的消息、文件与扩展配置将被删除</li><li>Agent 将退出已加入的项目，项目文件不受影响</li></ul></div><label>确定删除，请在下方输入：<strong>${E(expert.name)}</strong><input name="confirmName" autocomplete="off" placeholder="输入完整 Agent 名称"></label><footer><button type="button" data-r-action="wb-close-expert-delete">取消</button><button type="submit" class="danger" disabled>删除</button></footer></form>`;const form=$('#wb-expert-delete-form'),input=form.elements.confirmName,submit=form.querySelector('[type=submit]');input.oninput=()=>{submit.disabled=input.value!==expert.name;};form.onsubmit=event=>{event.preventDefault();if(input.value!==expert.name)return;workspace.experts=workspace.experts.filter(item=>item.id!==id);workspace.pinnedExpertIds=workspace.pinnedExpertIds.filter(item=>item!==id);workspace.usedExpertIds=workspace.usedExpertIds.filter(item=>item!==id);delete workspace.expertSettings[id];for(const project of workspace.projects){project.chats=(project.chats||[]).filter(item=>item.expert?.id!==id);if(project.id===state.id&&!project.chats.some(item=>item.id===state.chatId)){if(!project.chats.length)project.chats.push({id:uid(),title:'新对话',messages:[],draft:'',created:Date.now(),knowledge:null,connectors:null,reference:null,skillIds:[],presetIds:[],attachments:[]});state.chatId=project.chats[0].id;state.messages=project.chats[0].messages;}}persist();wbExpertDeleteDialog.close();renderAssistant();toast(`已删除专家「${expert.name}」`);};wbExpertDeleteDialog.showModal();input.focus();}
