function wbCollabInboxTasks(){const rows=[];for(const project of workspace.projects)for(const conversation of project.chats||[])for(const task of conversation.collaboration?.tasks||[])rows.push({...task,creator:task.creator||task.previousOwner||'张淼',agent:task.mode==='transfer'?task.agent:task.agent||conversation.expert?.name||'Default Agent',previousAgent:task.previousAgent||conversation.expert?.name||'Default Agent',source:conversation.title||project.name,projectId:project.id,chatId:conversation.id});const ids=new Set(rows.map(task=>task.id));return [...rows,...wbCollabDemoTasks.filter(task=>!ids.has(task.id))];}
function wbCollabTaskInboxCard(task){const waiting=task.status==='pending'&&task.assignee==='张淼',rejected=task.status==='rejected'&&task.creator==='张淼',created=task.demo?task.created:new Date(task.created||Date.now()).toLocaleDateString('zh-CN',{month:'long',day:'numeric'}),agentLabel=task.mode==='transfer'?(task.agent||'待选择'):task.agent||'Agent',agentMeta=task.mode==='transfer'?(task.agent?`已选择 ${task.agent}`:'接手后选择 Agent'):`截止 ${task.due||'未设置'}`;return `<article class="wb-task-inbox-card ${task.status}">${waiting?`<strong>✋ ${task.mode==='transfer'?'等待你接手':'等你回复'}</strong>`:rejected?'<strong>任务被拒绝 · 等待重新分派</strong>':''}<button data-r-action="wb-open-collab-task" data-id="${E(task.id)}" data-owner="${E(task.projectId||'')}" data-chat="${E(task.chatId||'')}"><header><div><small>${E(task.source)}</small><h3>${E(task.title)}</h3></div><span><i>${E(task.assignee.slice(0,1))}</i><i title="${E(agentLabel)}">${E(agentLabel.slice(0,1))}</i></span></header><p>${E(task.rejectionReason?`拒绝原因：${task.rejectionReason}`:task.deliverable)}</p><footer><span>${wbCollabStatus(task.status)} · ${E(task.assignee)}</span><span>${E(agentMeta)}</span><em>创建于 ${E(created)}</em></footer></button></article>`;}
function wbCollabTasksPage(){const all=wbCollabInboxTasks(),rows=all.filter(task=>WB.collabTaskTab==='all'||WB.collabTaskTab==='assigned'&&task.assignee==='张淼'||WB.collabTaskTab==='created'&&task.creator==='张淼'),groups=[['pending','待接收'],['rejected','需重新分派'],['processing','进行中'],['review','待验收'],['done','已完成']];return `<div class="wb-task-inbox"><header><div><small>MY TASKS</small><h1>我的任务</h1><p>集中处理指派给我的任务，以及我从会话中分派的工作。</p></div><button data-r-action="af-new">＋ 新建对话</button></header><nav aria-label="任务筛选">${[['all','全部'],['assigned','指派给我的'],['created','我创建的']].map(([id,label])=>`<button class="${WB.collabTaskTab===id?'active':''}" data-r-action="wb-collab-task-tab" data-id="${id}">${label}<span>${id==='all'?all.length:id==='assigned'?all.filter(task=>task.assignee==='张淼').length:all.filter(task=>task.creator==='张淼').length}</span></button>`).join('')}</nav><main class="wb-task-board">${groups.map(([status,label])=>{const items=rows.filter(task=>task.status===status);return `<section><header><h2><i class="${status}"></i>${label}</h2><span>${items.length}</span></header><div>${items.map(wbCollabTaskInboxCard).join('')||'<p class="wb-task-column-empty">暂无任务</p>'}</div></section>`;}).join('')}</main></div>`;}
R.invoke('wb-collab-task-tab',button=>{WB.collabTaskTab=button.dataset.id;wbRenderAgentPage();});
R.invoke('wb-open-collab-task',button=>{let owner=button.dataset.owner,chatId=button.dataset.chat;const demo=wbCollabDemoTasks.find(task=>task.id===button.dataset.id);if((!owner||!chatId)&&demo){const project=workspace.projects.find(item=>item.id===state.id)||workspace.projects[0];if(!project)return;const expert=wbAllExperts().find(item=>item.name===(demo.previousAgent||demo.agent)),task={...demo,demo:false,created:Date.now()};delete task.projectId;delete task.chatId;const intro=demo.mode==='transfer'?`【待接收的会话转让】${demo.creator}希望你接管当前会话。\n\n此前使用：${demo.previousAgent||'原 Agent'}\n交接说明：${demo.note||demo.deliverable}\n\n你可以先查看历史内容；接受时再选择自己需要的 Agent。`:`已进入协作任务「${demo.title}」。\n\n任务要求：${demo.deliverable}\n截止时间：${demo.due}\n当前状态：${wbCollabStatus(demo.status)}。`;const conversation={id:uid(),title:demo.source,messages:[{role:'assistant',text:intro,time:now()}],draft:'',created:Date.now(),knowledge:null,connectors:null,reference:null,skillIds:[],presetIds:[],attachments:[],collaboration:{owner:demo.creator,participants:[...new Set([demo.creator,demo.assignee])],tasks:[task]}};if(expert)wbApplyConversationExpert(conversation,expert,false);project.chats??=[];project.chats.unshift(conversation);owner=project.id;chatId=conversation.id;}if(!owner||!chatId)return;switchProject(owner);state.chatId=chatId;state.messages=awChat().messages;WB.agentSection='chat';WB.collabPanelOpen=false;persist();renderAssistant();});
const wbAssetKinds=[['finished','AI 成片','spark'],['video','视频原料','eye'],['image','图片原料','folder'],['cta','CTA 库','chat']];
const wbAssetFolderBlueprints={
 video:{'品牌与产品':['产品场景','功能演示'],'用户与口碑':['采访原片','用户证言']},
 image:{'品牌视觉':['主视觉','品牌元素'],'人物与场景':['人物素材','生活场景']},
 cta:{'转化文案':['按钮文案','落地页文案'],'活动促销':['结尾口播','优惠权益']}
};
function wbAssetPath(asset){
 if(asset.folder&&asset.subfolder)return {folder:asset.folder,subfolder:asset.subfolder};
 if(asset.kind==='video')return /采访|用户/.test(asset.name)?{folder:'用户与口碑',subfolder:/采访/.test(asset.name)?'采访原片':'用户证言'}:{folder:'品牌与产品',subfolder:/功能/.test(asset.name)?'功能演示':'产品场景'};
 if(asset.kind==='image')return /人物|场景/.test(asset.name)?{folder:'人物与场景',subfolder:/人物/.test(asset.name)?'人物素材':'生活场景'}:{folder:'品牌视觉',subfolder:/主视觉/.test(asset.name)?'主视觉':'品牌元素'};
 return /限时|权益|优惠|促销/.test(asset.name)?{folder:'活动促销',subfolder:/权益|优惠/.test(asset.name)?'优惠权益':'结尾口播'}:{folder:'转化文案',subfolder:/落地/.test(asset.name)?'落地页文案':'按钮文案'};
}
function wbAssetRows(kind=WB.assetTab){return workspace.assetLibrary.filter(asset=>asset.kind===kind).map(asset=>Object.assign({},asset,wbAssetPath(asset)));}
function wbAssetCard(asset){
 const glyph=asset.kind==='finished'?'spark':asset.kind==='video'?'eye':asset.kind==='image'?'folder':'chat';
 return `<article class="wb-asset-card" style="--asset-hue:${asset.hue||215}"><button class="wb-asset-preview" data-r-action="wb-preview-asset" data-id="${E(asset.id)}" aria-label="预览${E(asset.name)}"><span>${icon(glyph)}<b>${E(asset.format)}</b></span>${asset.kind==='cta'?`<q>${E(asset.name)}</q>`:`<i>${asset.kind==='finished'?'AI GENERATED':'SOURCE MATERIAL'}</i>`}<small>${E(asset.meta)}</small></button><div class="wb-asset-card-copy"><h3>${E(asset.name)}</h3><div>${(asset.tags||[]).map(tag=>`<span>${E(tag)}</span>`).join('')}</div><footer><small>${E(asset.creator)} · ${E(asset.created)}</small></footer></div></article>`;
}
function wbAssetFolderOpen(folder){return workspace.assetTree?.[WB.assetTab]?.[folder]!==false;}
function wbAssetFolderTree(rows){const folders=wbAssetFolderBlueprints[WB.assetTab]||{};return `<aside class="wb-asset-folder-tree"><header>${icon('folder')}<b>文件夹</b></header><button class="root ${WB.assetFolder==='all'?'active':''}" data-r-action="wb-asset-folder" data-folder="all">全部原料 <span>${rows.length}</span></button>${Object.entries(folders).map(([folder,subfolders])=>{const count=rows.filter(item=>item.folder===folder).length,open=wbAssetFolderOpen(folder);return `<section><button class="level-one ${WB.assetFolder===folder&&WB.assetSubfolder==='all'?'active':''}" data-r-action="wb-toggle-asset-folder" data-folder="${E(folder)}" aria-expanded="${open}" title="${open?'收起':'展开'}${E(folder)}"><i class="tree-chevron ${open?'open':''}">›</i>${icon('folder')}<span><b>${E(folder)}</b><small>${count}</small></span></button>${open?`<div>${subfolders.map(subfolder=>{const subCount=rows.filter(item=>item.folder===folder&&item.subfolder===subfolder).length;return `<button class="level-two ${WB.assetFolder===folder&&WB.assetSubfolder===subfolder?'active':''}" data-r-action="wb-asset-folder" data-folder="${E(folder)}" data-subfolder="${E(subfolder)}"><i></i>${E(subfolder)}<small>${subCount}</small></button>`;}).join('')}</div>`:''}</section>`;}).join('')}</aside>`;}
function wbAssetFileList(rows){if(!rows.length)return wbAgentEmpty('当前文件夹还没有原料');return `<div class="wb-asset-file-list"><header><span>名称</span><span>格式</span><span>标签</span><span>上传人</span><span>更新时间</span></header>${rows.map(asset=>{const glyph=asset.kind==='video'?'eye':asset.kind==='image'?'folder':'chat';return `<button data-r-action="wb-preview-asset" data-id="${E(asset.id)}"><span class="name"><i>${icon(glyph)}</i><b>${E(asset.name)}</b></span><span>${E(asset.format)}</span><span class="tags">${(asset.tags||[]).slice(0,2).map(tag=>`<em>${E(tag)}</em>`).join('')}</span><span>${E(asset.creator)}</span><span>${E(asset.created)}</span></button>`;}).join('')}</div>`;}
function wbRawAssetExplorer(allRows,queryRows){
 const folders=wbAssetFolderBlueprints[WB.assetTab]||{},searching=!!WB.assetQuery.trim();let content='',title='全部原料',crumb='全部原料';
 if(searching){title='搜索结果';crumb=`全部原料 / “${E(WB.assetQuery.trim())}”`;content=wbAssetFileList(queryRows);}else if(WB.assetFolder==='all'){content=`<div class="wb-asset-folder-grid">${Object.entries(folders).map(([folder,subfolders])=>`<button data-r-action="wb-asset-folder" data-folder="${E(folder)}" data-subfolder="all">${icon('folder')}<span><b>${E(folder)}</b><small>${subfolders.length} 个文件夹 · ${allRows.filter(item=>item.folder===folder).length} 条原料</small></span></button>`).join('')}</div>`;}else if(WB.assetSubfolder==='all'){title=WB.assetFolder;crumb=`全部原料 / ${E(WB.assetFolder)}`;content=`<div class="wb-asset-folder-grid">${(folders[WB.assetFolder]||[]).map(subfolder=>`<button data-r-action="wb-asset-folder" data-folder="${E(WB.assetFolder)}" data-subfolder="${E(subfolder)}">${icon('folder')}<span><b>${E(subfolder)}</b><small>${allRows.filter(item=>item.folder===WB.assetFolder&&item.subfolder===subfolder).length} 条原料</small></span></button>`).join('')}</div>`;}else{title=WB.assetSubfolder;crumb=`全部原料 / ${E(WB.assetFolder)} / ${E(WB.assetSubfolder)}`;content=wbAssetFileList(allRows.filter(item=>item.folder===WB.assetFolder&&item.subfolder===WB.assetSubfolder));}
 return `<section class="wb-asset-explorer">${wbAssetFolderTree(allRows)}<main><header><small>${crumb}</small><h2>${E(title)}</h2></header>${content}</main></section>`;
}
function wbAssetsPage(){
 const query=WB.assetQuery.trim().toLowerCase(),allRows=wbAssetRows(),queryRows=allRows.filter(asset=>(asset.name+' '+asset.creator+' '+(asset.tags||[]).join(' ')+' '+(asset.folder||'')+' '+(asset.subfolder||'')).toLowerCase().includes(query)),raw=WB.assetTab!=='finished';
 return `<div class="wb-assets-page"><header class="wb-assets-head"><div class="wb-assets-title"><small>ASSET LIBRARY</small><h1>资产库</h1><p>集中管理 AI 生成的成片，以及按文件夹归档的视频、图片和 CTA 原料。</p></div></header><div class="wb-assets-toolbar"><nav>${wbAssetKinds.map(([kind,label])=>`<button class="${WB.assetTab===kind?'active':''}" data-r-action="wb-asset-tab" data-id="${kind}">${label}</button>`).join('')}</nav><div class="wb-assets-toolbar-actions">${raw?'<button class="wb-asset-upload-trigger" data-r-action="wb-open-asset-upload">＋ 上传原料</button>':''}<label>${icon('search')}<input id="wb-asset-query" aria-label="搜索资产" placeholder="搜索名称、标签或文件夹" value="${E(WB.assetQuery)}"></label><span>共 ${queryRows.length} 项</span></div></div>${raw?wbRawAssetExplorer(allRows,queryRows):`<section class="wb-assets-grid">${queryRows.map(wbAssetCard).join('')||wbAgentEmpty('没有找到匹配的成片')}</section>`}</div>`;
}
