function wbOpenAssetPreview(id){const asset=workspace.assetLibrary.find(item=>item.id===id);if(!asset)return;const glyph=asset.kind==='finished'?'spark':asset.kind==='video'?'eye':asset.kind==='image'?'folder':'chat',path=asset.kind==='finished'?null:wbAssetPath(asset);wbAssetPreviewDialog.innerHTML=`<div class="wb-asset-preview-shell"><header><div><small>${E(asset.format)} · ${E(asset.created)}</small><h2>${E(asset.name)}</h2></div><button data-r-action="wb-close-asset-preview" aria-label="关闭">×</button></header><main style="--asset-hue:${asset.hue||215}"><section class="wb-asset-preview-stage">${icon(glyph)}<b>${asset.kind==='cta'?`“${E(asset.name)}”`:'资产预览'}</b><small>${E(asset.meta)}</small></section><aside><h3>资产信息</h3><dl><div><dt>类型</dt><dd>${E(wbAssetKinds.find(row=>row[0]===asset.kind)?.[1]||asset.kind)}</dd></div><div><dt>上传人</dt><dd>${E(asset.creator)}</dd></div><div><dt>来源</dt><dd>${asset.kind==='finished'?'AI 生成':'原料库上传'}</dd></div>${path?`<div><dt>文件夹</dt><dd>${E(path.folder)} / ${E(path.subfolder)}</dd></div>`:''}<div><dt>标签</dt><dd>${(asset.tags||[]).map(E).join('、')}</dd></div></dl></aside></main></div>`;wbAssetPreviewDialog.showModal();}
