function wbAssetUploadConfig(kind){return kind==='video'?{label:'视频',accept:'video/mp4,video/webm,video/quicktime,.mp4,.webm,.mov',help:'支持 MP4、WebM、MOV，单个视频不超过 100 MB'}:kind==='image'?{label:'图片',accept:'image/jpeg,image/png,image/webp,.jpg,.jpeg,.png,.webp',help:'支持 JPG、PNG、WebP，单张图片不超过 10 MB'}:{label:'CTA',accept:'.txt,.csv,.xls,.xlsx,text/plain,text/csv',help:'支持 TXT、CSV、Excel，可批量导入 CTA 文案'};}
function wbDrawAssetUpload(){
 const kind=WB.assetTab,config=wbAssetUploadConfig(kind),folders=wbAssetFolderBlueprints[kind],folder=WB.assetUploadFolder&&folders[WB.assetUploadFolder]?WB.assetUploadFolder:Object.keys(folders)[0],subfolders=folders[folder],subfolder=subfolders.includes(WB.assetUploadSubfolder)?WB.assetUploadSubfolder:subfolders[0];WB.assetUploadFolder=folder;WB.assetUploadSubfolder=subfolder;
 wbAssetUploadDialog.innerHTML=`<form id="wb-asset-upload-form"><header><div><small>MATERIAL LIBRARY</small><h2>上传${config.label}原料</h2><p>选择归档文件夹后，从本地添加原料文件。</p></div><button type="button" data-r-action="wb-close-asset-upload" aria-label="关闭">×</button></header><main><div class="wb-asset-upload-folders"><label><b>一级文件夹</b><select id="wb-asset-upload-folder">${Object.keys(folders).map(name=>`<option ${name===folder?'selected':''}>${E(name)}</option>`).join('')}</select></label><label><b>二级文件夹</b><select id="wb-asset-upload-subfolder">${subfolders.map(name=>`<option ${name===subfolder?'selected':''}>${E(name)}</option>`).join('')}</select></label></div><section class="wb-asset-upload-zone" id="wb-asset-dropzone" tabindex="0" role="button" aria-label="拖拽文件或本地上传"><span>${icon('folder')}</span><p>将文件拖到此处，或 <button type="button" id="wb-asset-local-upload">本地上传</button></p><small>${config.help}；每次最多 20 个文件</small><input hidden type="file" id="wb-asset-upload-input" multiple accept="${config.accept}"></section><div class="wb-asset-upload-files">${(WB.assetUploadFiles||[]).map((file,index)=>`<article><i>${icon(kind==='video'?'eye':kind==='image'?'folder':'chat')}</i><span><b>${E(file.name)}</b><small>${Math.max(1,Math.round(file.size/1024))} KB · 待上传</small></span><button type="button" data-r-action="wb-remove-asset-upload" data-id="${index}" aria-label="移除${E(file.name)}">×</button></article>`).join('')}</div></main><footer><span>${WB.assetUploadFiles.length?`已选择 ${WB.assetUploadFiles.length} 个文件`:'请选择要上传的原料文件'}</span><button type="button" data-r-action="wb-close-asset-upload">取消</button><button type="submit" class="solid" ${WB.assetUploadFiles.length?'':'disabled'}>开始上传</button></footer></form>`;
 const form=$('#wb-asset-upload-form'),input=$('#wb-asset-upload-input'),zone=$('#wb-asset-dropzone'),addFiles=files=>{WB.assetUploadFiles.push(...[...files].slice(0,Math.max(0,20-WB.assetUploadFiles.length)));wbDrawAssetUpload();};
 $('#wb-asset-upload-folder').onchange=e=>{WB.assetUploadFolder=e.target.value;WB.assetUploadSubfolder=(folders[WB.assetUploadFolder]||[])[0];wbDrawAssetUpload();};$('#wb-asset-upload-subfolder').onchange=e=>WB.assetUploadSubfolder=e.target.value;$('#wb-asset-local-upload').onclick=()=>input.click();zone.onclick=e=>{if(!e.target.closest('button'))input.click();};zone.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();input.click();}};zone.ondragover=e=>{e.preventDefault();zone.classList.add('dragging');};zone.ondragleave=()=>zone.classList.remove('dragging');zone.ondrop=e=>{e.preventDefault();zone.classList.remove('dragging');addFiles(e.dataTransfer.files);};input.onchange=()=>addFiles(input.files);
 form.onsubmit=e=>{e.preventDefault();if(!WB.assetUploadFiles.length)return;for(const file of WB.assetUploadFiles){const ext=(file.name.split('.').pop()||kind).toUpperCase();workspace.assetLibrary.unshift({id:uid(),kind,name:file.name.replace(/\.[^.]+$/,''),format:ext,meta:`${Math.max(1,Math.round(file.size/1024))} KB · 本地上传`,creator:'张淼',created:'刚刚',hue:kind==='image'?228:kind==='video'?182:18,tags:[kind==='cta'?'CTA':'原料','本地上传','待整理'],folder:WB.assetUploadFolder,subfolder:WB.assetUploadSubfolder});}const count=WB.assetUploadFiles.length;WB.assetUploadFiles=[];WB.assetFolder=WB.assetUploadFolder;WB.assetSubfolder=WB.assetUploadSubfolder;persist();wbAssetUploadDialog.close();wbRenderAgentPage();toast(`已上传 ${count} 个${config.label}原料`);};
}
R.invoke('wb-open-asset-upload',()=>{WB.assetUploadFiles=[];WB.assetUploadFolder=WB.assetFolder==='all'?'':WB.assetFolder;WB.assetUploadSubfolder=WB.assetSubfolder==='all'?'':WB.assetSubfolder;wbDrawAssetUpload();wbAssetUploadDialog.showModal();});
R.invoke('wb-close-asset-upload',()=>wbAssetUploadDialog.close());
R.invoke('wb-remove-asset-upload',button=>{WB.assetUploadFiles.splice(Number(button.dataset.id),1);wbDrawAssetUpload();});
function wbAppsPage(){
 const applications=[{id:'inspiration',name:'灵感库',description:'发现优质内容与热门趋势，进入内容洞察和热点洞察。',meta:'内容洞察 · 热点洞察'}];
 const query=WB.appQuery.trim().toLowerCase(),rows=applications.filter(app=>(app.name+' '+app.description+' '+app.meta).toLowerCase().includes(query));
 return `<header class="wb-apps-head"><div><h1>应用</h1><p>选择应用进入对应工作空间</p></div><label class="wb-app-search" aria-label="搜索应用">${icon('search')}<input id="wb-app-query" placeholder="搜索应用" value="${E(WB.appQuery)}"></label></header><div class="wb-apps-body"><div class="wb-app-grid">${rows.map(app=>`<button type="button" class="wb-app-card" data-r-action="wb-open-app" data-id="${E(app.id)}"><span class="wb-app-icon">${icon('spark')}</span><span class="wb-app-copy"><b>${E(app.name)}</b><small>${E(app.description)}</small><em>${E(app.meta)}</em></span><span class="wb-app-arrow">进入 →</span></button>`).join('')||wbAgentEmpty('没有找到匹配的应用')}</div></div>`;
}
function wbRenderAgentPage(){
 const section=WB.agentSection,active=section!=='chat'&&assistantShell.dataset.presentation==='page';
 assistantShell.classList.toggle('wb-inner-page',active);
 afRail.querySelectorAll('button').forEach(b=>{const selected=({'af-new':'chat','wb-my-tasks':'collab-tasks','wb-automation':'automation','af-config':'knowledge','af-skills':'skills','wb-experts':'experts','wb-assets':'assets','wb-apps':'apps'})[b.dataset.rAction]===section;b.classList.toggle('active',selected);if(selected)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});
 if(!active)return;
 wbAgentPage.innerHTML=section==='collab-tasks'?wbCollabTasksPage():section==='automation'?wbAutomationPage():section==='knowledge'?wbKnowledgePage():section==='skills'?wbSkillsPage():section==='experts'?wbExpertPage():section==='assets'?wbAssetsPage():wbAppsPage();
 const bindQuery=(id,key)=>{const el=$(id);if(el)el.oninput=e=>{WB[key]=e.target.value;const pos=e.target.selectionStart;wbRenderAgentPage();$(id).focus();$(id).setSelectionRange(pos,pos);};};
 bindQuery('#wb-task-query','taskQuery');bindQuery('#wb-knowledge-query','knowledgeQuery');bindQuery('#wb-member-query','knowledgeMemberQuery');bindQuery('#wb-project-query','knowledgeProjectQuery');bindQuery('#wb-skill-query','skillQuery');bindQuery('#wb-expert-query','expertQuery');bindQuery('#wb-asset-query','assetQuery');bindQuery('#wb-app-query','appQuery');
 if($('#wb-task-status'))$('#wb-task-status').onchange=e=>{WB.taskStatus=e.target.value;wbRenderAgentPage();};
 if($('#wb-knowledge-sort'))$('#wb-knowledge-sort').onchange=e=>{WB.knowledgeSort=e.target.value;wbRenderAgentPage();};
 if($('#wb-log-query'))$('#wb-log-query').onchange=e=>{WB.knowledgeLogQuery=e.target.value;wbRenderAgentPage();};
 if($('#wb-team-settings'))$('#wb-team-settings').onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));Object.assign(workspace.knowledgeTeam,values);wbTeamLog('修改团队设置',values.name);persist();wbRenderAgentPage();toast('团队设置已保存');};
 if($('#skill-file-input'))$('#skill-file-input').onchange=R.importSkill;
}
