const wbKnowledgeUploadDialog=document.createElement('dialog');wbKnowledgeUploadDialog.id='wb-knowledge-upload-dialog';wbKnowledgeUploadDialog.setAttribute('aria-label','上传知识');document.body.append(wbKnowledgeUploadDialog);
function wbRenderKnowledgeUploadFiles(){const host=$('#wb-knowledge-upload-files');if(!host)return;const files=WB.knowledgeDraftFiles||[];host.innerHTML=files.map((file,index)=>`<span>${icon('book')}<b>${E(file.name)}</b><small>${file.size?Math.max(1,Math.round(file.size/1024))+' KB':'已上传'}</small><button type="button" data-r-action="wb-remove-knowledge-file" data-id="${index}" aria-label="移除${E(file.name)}">×</button></span>`).join('');}
function wbKnowledgeForm(id,requestedFolderId=''){
 const knowledge=workspace.knowledge.find(item=>item.id===id),folderId=knowledge?.folderId||requestedFolderId||workspace.knowledgeFolders[0]?.id||'';WB.knowledgeDraftFiles=(knowledge?.files||[]).map(file=>({...file}));
 wbKnowledgeUploadDialog.innerHTML=`<form id="wb-knowledge-upload-form"><header><div><small>KNOWLEDGE</small><h2>${knowledge?'编辑知识':'上传知识'}</h2><p>填写知识名称，并上传可供专家和对话引用的文件。</p></div><button type="button" data-r-action="wb-close-knowledge-upload" aria-label="关闭">×</button></header><main><input type="hidden" name="folderId" value="${E(folderId)}"><label class="wb-knowledge-upload-name"><b>知识名称</b><input name="name" required maxlength="60" value="${E(knowledge?.name||'')}" placeholder="例如：品牌规范与产品资料"></label><section class="wb-knowledge-upload-box"><b>上传文件</b><label><input id="wb-knowledge-file-input" type="file" multiple accept=".xls,.xlsx,.doc,.docx,.pdf,.txt,.md,.markdown"><strong>＋</strong><span>点击上传知识文件</span></label><p>支持上传 Excel、Word、PDF、TXT、Markdown 格式的文件</p><div id="wb-knowledge-upload-files"></div></section>${knowledge?.content&&!knowledge?.files?.length?'<p class="wb-knowledge-legacy">已有知识内容将被保留；上传文件后会更新为文件资料。</p>':''}</main><footer><button type="button" data-r-action="wb-close-knowledge-upload">取消</button><button type="submit" class="solid">${knowledge?'保存':'上传知识'}</button></footer></form>`;
 const form=$('#wb-knowledge-upload-form'),input=$('#wb-knowledge-file-input');wbRenderKnowledgeUploadFiles();input.onchange=async()=>{const files=[...input.files||[]];for(const file of files){let text='';if(/\.(txt|md|markdown)$/i.test(file.name))try{text=await file.text();}catch{}WB.knowledgeDraftFiles.push({name:file.name,type:file.type,size:file.size,text});}input.value='';wbRenderKnowledgeUploadFiles();};form.onsubmit=event=>{event.preventDefault();const name=form.elements.name.value.trim(),selectedFolderId=form.elements.folderId.value,files=WB.knowledgeDraftFiles||[];if(!name)return toast('请填写知识名称');if(!selectedFolderId)return toast('请先新建一级文件夹');if(!files.length&&!knowledge?.content)return toast('请先点击＋上传知识文件');const content=files.length?files.map(file=>file.text||`已上传文件：${file.name}`).join('\n\n'):knowledge.content,values={name,folderId:selectedFolderId,content,files:files.map(({name,type,size,text})=>({name,type,size,text})),updated:now()};if(knowledge)Object.assign(knowledge,values);else workspace.knowledge.push({...values,id:uid(),created:now()});persist();wbKnowledgeUploadDialog.close();wbRenderAgentPage();toast(knowledge?'知识已更新':'知识上传完成');};wbKnowledgeUploadDialog.showModal();form.elements.name.focus();
}
R.invoke('wb-new-knowledge-folder',()=>{modal('新建一级文件夹','一级文件夹用于组织知识；创建后可在文件夹中上传具体资料。',[{key:'name',label:'文件夹名称',required:true,max:40}],values=>{const name=values.name.trim();if(workspace.knowledgeFolders.some(folder=>folder.name===name))throw Error('已存在同名文件夹');workspace.knowledgeFolders.push({id:uid(),name,created:now()});wbTeamLog('创建文件夹',name);wbRenderAgentPage();toast(`已新建一级文件夹「${name}」`);});$('#save').textContent='创建';});
R.invoke('wb-rename-knowledge-folder',button=>{const folder=workspace.knowledgeFolders.find(item=>item.id===button.dataset.id);if(!folder)return;modal('重命名文件夹','修改一级文件夹名称，文件夹内的知识不会发生变化。',[{key:'name',label:'文件夹名称',required:true,max:40,value:folder.name}],values=>{const name=values.name.trim();if(workspace.knowledgeFolders.some(item=>item.id!==folder.id&&item.name===name))throw Error('已存在同名文件夹');const previous=folder.name;folder.name=name;wbTeamLog('重命名文件夹',`${previous} → ${name}`);persist();wbRenderAgentPage();toast('文件夹已重命名');});$('#save').textContent='保存';});
R.invoke('wb-delete-knowledge-folder',button=>{const folder=workspace.knowledgeFolders.find(item=>item.id===button.dataset.id);if(!folder)return;const documents=workspace.knowledge.filter(item=>item.folderId===folder.id);modal('删除知识文件夹',documents.length?`“${folder.name}”中有 ${documents.length} 个文档，删除文件夹会同时删除这些文档，且不能恢复。`:`确认删除空文件夹“${folder.name}”？`,[],()=>{const removedIds=new Set(documents.map(item=>item.id));workspace.knowledgeFolders=workspace.knowledgeFolders.filter(item=>item.id!==folder.id);workspace.knowledge=workspace.knowledge.filter(item=>item.folderId!==folder.id);for(const project of workspace.projects){if(project.bindings?.knowledge)project.bindings.knowledge=project.bindings.knowledge.filter(id=>!removedIds.has(id));for(const conversation of project.chats||[])if(conversation.knowledge)conversation.knowledge=conversation.knowledge.filter(id=>!removedIds.has(id));}for(const expert of workspace.experts||[])if(expert.knowledgeIds)expert.knowledgeIds=expert.knowledgeIds.filter(id=>!removedIds.has(id));if(WB.knowledgeFolderId===folder.id)WB.knowledgeFolderId='';wbTeamLog('删除文件夹',folder.name);persist();wbRenderAgentPage();toast(`已删除文件夹「${folder.name}」`);});$('#save').textContent='删除';});
R.invoke('wb-new-knowledge',button=>wbKnowledgeForm('',button.dataset.owner));R.invoke('wb-edit-knowledge',b=>wbKnowledgeForm(b.dataset.id));
R.invoke('wb-rename-knowledge',button=>{const knowledge=workspace.knowledge.find(item=>item.id===button.dataset.id);if(!knowledge)return;modal('重命名知识','只修改知识名称，已上传文件与引用关系保持不变。',[{key:'name',label:'知识名称',required:true,max:60,value:knowledge.name}],values=>{knowledge.name=values.name.trim();knowledge.updated=now();persist();wbRenderAgentPage();toast('知识已重命名');});$('#save').textContent='保存';});
R.invoke('wb-delete-knowledge',button=>{const knowledge=workspace.knowledge.find(item=>item.id===button.dataset.id);if(!knowledge)return;modal('删除知识',`确认删除“${knowledge.name}”？删除后无法恢复。`,[],()=>{workspace.knowledge=workspace.knowledge.filter(item=>item.id!==knowledge.id);for(const project of workspace.projects){if(project.bindings?.knowledge)project.bindings.knowledge=project.bindings.knowledge.filter(id=>id!==knowledge.id);for(const conversation of project.chats||[])if(conversation.knowledge)conversation.knowledge=conversation.knowledge.filter(id=>id!==knowledge.id);}for(const expert of workspace.experts||[])if(expert.knowledgeIds)expert.knowledgeIds=expert.knowledgeIds.filter(id=>id!==knowledge.id);persist();wbRenderAgentPage();toast('知识已删除');});$('#save').textContent='删除';});
