function wbChatCollaboration(){const conversation=awChat();conversation.collaboration??={owner:'张淼',participants:['张淼'],tasks:[]};return conversation.collaboration;}
function wbCollabStatus(status){return ({pending:'待接收',rejected:'已拒绝',processing:'进行中',review:'待验收',done:'已完成'})[status]||status;}
function wbCollabButtons(task){const current='张淼',isAssignee=task.assignee===current,isCreator=(task.creator||task.previousOwner)===current;if(task.status==='pending')return isAssignee?`<button class="solid" data-r-action="wb-collab-accept" data-id="${E(task.id)}">${task.mode==='transfer'?'接受并选择 Agent':'接收任务'}</button><button data-r-action="wb-collab-reject" data-id="${E(task.id)}">拒绝接收</button>`:`<button disabled>等待${E(task.assignee)}接收</button>`;if(task.status==='rejected')return isCreator?`<button class="solid" data-r-action="wb-collab-reassign" data-id="${E(task.id)}">${task.mode==='transfer'?'重新转让':'修改后重派'}</button>`:'<button disabled>已拒绝</button>';if(task.mode==='transfer'&&task.status==='done')return `<button disabled>${task.agent?`已使用 ${E(task.agent)} 接手`:'已完成交接'}</button>`;if(task.status==='processing')return isAssignee?`<button class="solid" data-r-action="wb-collab-submit" data-id="${E(task.id)}">提交结果</button>`:isCreator?`<button data-r-action="wb-collab-remind" data-id="${E(task.id)}">催办</button>`:'';if(task.status==='review')return isCreator?`<button class="solid" data-r-action="wb-collab-confirm" data-id="${E(task.id)}">确认完成</button><button data-r-action="wb-collab-revise" data-id="${E(task.id)}">要求修改</button>`:'<button disabled>等待发起人验收</button>';return task.mode==='transfer'?'<button disabled>已完成交接</button>':task.assetSaved?'<button disabled>已保存至资产库</button>':isCreator?`<button class="solid" data-r-action="wb-save-task-asset" data-id="${E(task.id)}">保存至资产库</button>`:'';}
function wbCollabTaskCard(task){return `<div class="wb-collab-line ${task.status}"><small>${task.mode==='transfer'?'会话转让':'协作任务'} · ${E(task.assignee)} · ${wbCollabStatus(task.status)}</small><p><b>${E(task.title)}</b></p><p>${E(task.deliverable)}</p>${task.rejectionReason?`<p class="wb-collab-rejection"><b>${E(task.assignee)}拒绝接收：</b>${E(task.rejectionReason)}${task.suggestedAssignee?`<span>建议改派给 ${E(task.suggestedAssignee)}</span>`:''}</p>`:''}${task.result?`<p><b>${task.mode==='transfer'?'交接结果：':'提交结果：'}</b>${E(task.result)}</p>`:''}<p class="wb-collab-meta">截止 ${E(task.due||'未设置')} · ${task.shareAssets?'可使用资产库':'仅共享当前会话'}${task.autoReturn?' · 完成后交回主负责人':''}</p><footer>${wbCollabButtons(task)}</footer></div>`;}
function wbOpenHandoff(mode='assign',existingTask=null){
 const collab=wbChatCollaboration(),experts=wbAllExperts(),people=mode==='transfer'?workspace.collaborationMembers:[...new Set([...workspace.collaborationMembers,...experts.map(expert=>expert.name)])],tomorrow=new Date(Date.now()+86400000).toISOString().slice(0,10),transfer=mode==='transfer',currentAgent=awChat().expert?.name||'Default Agent';
 const preferredAssignee=existingTask?.suggestedAssignee||existingTask?.assignee,title=existingTask?.title||(transfer?`接管「${awChat().title||'当前会话'}」`:'完成当前会话中的专项工作'),deliverable=existingTask?.deliverable||(transfer?'已完成前期方案确认，请继续推进后续工作，并在关键节点同步进度。':'提交可直接审核的结果，并说明关键选择与待确认项。');
 wbHandoffDialog.innerHTML=`<form id="wb-handoff-form"><header><div><small>COLLABORATION</small><h2>${existingTask?(transfer?'重新转交会话':'重新分派任务'):(transfer?'转交会话':'分派任务')}</h2><p>${existingTask?'修改执行人或任务要求后重新发送。':transfer?'接收人确认后成为当前负责人，原负责人继续保留为参与人。':'从当前会话拆出一项具体工作，完成后把结果回写到这里。'}</p></div><button type="button" data-r-action="wb-close-handoff" aria-label="关闭">×</button></header><main><input type="hidden" name="mode" value="${mode}"><div class="wb-handoff-grid"><label><b>${transfer?'接收人':'执行人'}</b><select name="assignee">${people.filter(name=>name!==collab.owner).map(name=>`<option ${name===preferredAssignee?'selected':''}>${E(name)}</option>`).join('')}</select></label><label><b>截止时间</b><input type="date" name="due" value="${E(existingTask?.due?.match(/^\d{4}-\d{2}-\d{2}$/)?.[0]||tomorrow)}"></label></div><label><b>${transfer?'接收后使用的 Agent':'执行 Agent'}</b><select name="agent">${experts.map(expert=>`<option ${expert.name===(existingTask?.agent||currentAgent)?'selected':''}>${E(expert.name)}</option>`).join('')}</select></label><label><b>${transfer?'交接主题':'任务名称'}</b><input name="title" required value="${E(title)}" placeholder="${transfer?'例如：继续负责后续视觉制作':'例如：生成三版视频封面'}"></label><label><b>${transfer?'交接说明':'交付结果'}</b><textarea name="deliverable" required>${E(deliverable)}</textarea></label><section class="wb-handoff-scope"><b>共享范围</b><label><input type="checkbox" name="shareContext" checked disabled> 当前会话上下文</label><label><input type="checkbox" name="shareKnowledge" ${existingTask&&!existingTask.shareKnowledge?'':'checked'}> 已选知识</label><label><input type="checkbox" name="shareAssets" ${existingTask&&!existingTask.shareAssets?'':'checked'}> 当前项目资产</label>${transfer?`<label><input type="checkbox" name="autoReturn" ${existingTask?.autoReturn?'checked':''}> 完成后交回原负责人</label>`:''}</section></main><footer><button type="button" data-r-action="wb-close-handoff">取消</button><button class="solid" type="submit">${existingTask?'重新发送':transfer?'发送转交':'确认分派'}</button></footer></form>`;
 const form=$('#wb-handoff-form');form.onsubmit=event=>{event.preventDefault();const data=Object.fromEntries(new FormData(form)),values={mode:data.mode,assignee:data.assignee,agent:data.agent,title:data.title.trim(),deliverable:data.deliverable.trim(),due:data.due,status:'pending',shareContext:true,shareKnowledge:!!data.shareKnowledge,shareAssets:!!data.shareAssets,autoReturn:!!data.autoReturn,previousOwner:existingTask?.previousOwner||collab.owner};let task;if(existingTask){task=existingTask;Object.assign(task,values,{reassignedAt:Date.now(),creatorAlert:false});delete task.rejectionReason;delete task.suggestedAssignee;delete task.rejectedAt;}else{task={id:uid(),...values,creator:collab.owner,created:Date.now()};collab.tasks.unshift(task);}if(!collab.participants.includes(task.assignee))collab.participants.push(task.assignee);WB.collabPanelOpen=true;persist();wbHandoffDialog.close();renderAssistant();toast(existingTask?`已重新发送给${task.assignee}`:transfer?`已向${task.assignee}发送会话转交`:`已向${task.assignee}分派任务`);};
 wbHandoffDialog.showModal();
}
function wbOpenConversationTransfer(existingTask=null){
 const collab=wbChatCollaboration(),members=workspace.collaborationMembers.filter(name=>name!==collab.owner),preferred=existingTask?.suggestedAssignee||existingTask?.assignee||'',conversation=awChat();
 wbHandoffDialog.innerHTML=`<form id="wb-transfer-form"><header><div><small>TRANSFER CONVERSATION</small><h2>${existingTask?'重新转让对话':'转让对话'}</h2><p>选择一位成员。对方接受时自行选择后续 Agent，拒绝时负责人保持不变。</p></div><button type="button" data-r-action="wb-close-handoff" aria-label="关闭">×</button></header><main><label class="wb-transfer-search">${icon('search')}<input name="query" autocomplete="off" placeholder="搜索成员"></label><section class="wb-transfer-members">${members.map(name=>`<label data-name="${E(name.toLowerCase())}"><input type="radio" name="assignee" value="${E(name)}" ${name===preferred?'checked':''}><span>${E(name.slice(0,1))}</span><b>${E(name)}</b><small>团队成员</small><i>✓</i></label>`).join('')||'<p>当前没有可转让的团队成员。</p>'}</section><label class="wb-transfer-note"><b>交接说明 <small>选填</small></b><textarea name="note" maxlength="300" placeholder="例如：请继续推进后续素材制作，并在关键节点同步进度。">${E(existingTask?.note||'')}</textarea></label><p class="wb-transfer-permission">申请发出后，当前负责人仍可继续处理；对方接受并选定 Agent 后才获得负责人权限。</p></main><footer><button type="button" data-r-action="wb-close-handoff">取消</button><button class="solid" type="submit" ${preferred?'':'disabled'}>${existingTask?'重新发送':'发送转让'}</button></footer></form>`;
 const form=$('#wb-transfer-form'),search=form.elements.query,submit=form.querySelector('[type="submit"]');
 form.onchange=()=>{submit.disabled=!form.elements.assignee.value;};
 search.oninput=()=>{const query=search.value.trim().toLowerCase();form.querySelectorAll('.wb-transfer-members>label').forEach(label=>label.hidden=query&&!label.dataset.name.includes(query));};
 form.onsubmit=event=>{event.preventDefault();const data=Object.fromEntries(new FormData(form)),assignee=data.assignee;if(!assignee)return;const values={mode:'transfer',assignee,agent:'',previousAgent:conversation.expert?.name||'Default Agent',title:`接管「${conversation.title||'当前会话'}」`,deliverable:data.note.trim()||'请接管当前会话并继续处理后续工作。',note:data.note.trim(),due:'未设置',status:'pending',shareContext:true,shareKnowledge:true,shareAssets:true,autoReturn:false,previousOwner:existingTask?.previousOwner||collab.owner};let task;if(existingTask){task=existingTask;Object.assign(task,values,{reassignedAt:Date.now(),creatorAlert:false});delete task.rejectionReason;delete task.suggestedAssignee;delete task.rejectedAt;}else{task={id:uid(),...values,creator:collab.owner,created:Date.now()};collab.tasks.unshift(task);}if(!collab.participants.includes(assignee))collab.participants.push(assignee);conversation.messages.push({role:'assistant',text:`【会话转让】${collab.owner}申请将当前会话转让给${assignee}，等待对方接收。${task.note?`\n交接说明：${task.note}`:''}\n接收人将在接受时自行选择后续使用的 Agent。`,time:now()});state.messages=conversation.messages;WB.collabPanelOpen=false;persist();wbHandoffDialog.close();renderAssistant();toast(`已向${assignee}发送会话转让申请`);};
 wbHandoffDialog.showModal();
 search.focus();
}
function wbOpenTransferAcceptance(task){
 if(!task||task.mode!=='transfer')return;
 const conversation=awChat(),experts=wbAllExperts(),previousAgent=task.previousAgent||conversation.expert?.name||'原 Agent';
 wbTransferAcceptDialog.innerHTML=`<form id="wb-transfer-accept-form"><header><div><small>ACCEPT CONVERSATION</small><h2>接受会话并选择 Agent</h2><p>先确认交接内容，再选择你要用于后续工作的 Agent。</p></div><button type="button" data-r-action="wb-close-transfer-accept" aria-label="关闭">×</button></header><main><section class="wb-transfer-summary"><span>${E((task.previousOwner||task.creator||'原负责人').slice(0,1))}</span><div><small>${E(task.previousOwner||task.creator||'原负责人')} 转交给你</small><b>${E(task.title)}</b><p>${E(task.note||task.deliverable)}</p></div></section><div class="wb-transfer-agent-head"><div><b>选择接手 Agent</b><small>仅影响接手后的新消息，${E(previousAgent)} 的历史内容会完整保留。</small></div><em>必选</em></div><section class="wb-transfer-agent-list">${experts.map(expert=>`<label><input type="radio" name="expert" value="${E(expert.id)}"><span>${wbExpertAvatarMarkup(expert.avatar,expert.name.slice(0,1))}</span><div><b>${E(expert.name)}</b><small>${E(expert.description||expert.category||'专属工作 Agent')}</small></div><i>✓</i></label>`).join('')}</section><p class="wb-transfer-permission">确认后，你将成为会话负责人；当前会话、历史消息和已共享资料保持不变。</p></main><footer><button type="button" data-r-action="wb-close-transfer-accept">暂不接收</button><button class="solid" type="submit" disabled>确认接手</button></footer></form>`;
 const form=$('#wb-transfer-accept-form'),submit=form.querySelector('[type="submit"]');
 form.onchange=()=>{submit.disabled=!form.elements.expert.value;};
 form.onsubmit=event=>{event.preventDefault();const expert=wbFindExpert(new FormData(form).get('expert'));if(!expert)return;task.previousAgent=previousAgent;task.agent=expert.name;task.status='done';task.acceptedAt=Date.now();task.result=`${task.assignee}已接受会话转让，并选择${expert.name}继续处理。`;wbChatCollaboration().owner=task.assignee;wbApplyConversationExpert(conversation,expert,false);conversation.messages.push({role:'assistant',text:`【会话转让完成】${task.assignee}已接受转让，成为当前负责人。\n\n后续工作由「${expert.name}」继续处理。系统已继承完整历史、已选知识、附件、资产和交接说明；「${previousAgent}」的历史输出保持原样。`,time:now(),agentSwitch:true});state.messages=conversation.messages;persist();wbTransferAcceptDialog.close();renderAssistant();toast(`已使用${expert.name}接手会话`);};
 wbTransferAcceptDialog.showModal();
}
function wbFindCollabTask(id){return wbChatCollaboration().tasks.find(task=>task.id===id);}
function wbSetCollabStatus(id,status,message){const task=wbFindCollabTask(id);if(!task)return;task.status=status;if(status==='processing'&&task.mode==='transfer')wbChatCollaboration().owner=task.assignee;if(status==='review')task.result=`${task.assignee} 已提交结果：${task.title}已完成，相关文件与说明已附在当前会话。`;if(status==='done'&&task.autoReturn)wbChatCollaboration().owner=task.previousOwner;persist();renderAssistant();toast(message);}
function wbOpenRejectTask(id){const task=wbFindCollabTask(id);if(!task)return;const suggestions=['暂无建议',...workspace.collaborationMembers.filter(name=>name!==task.assignee&&name!==task.creator)];wbRejectDialog.innerHTML=`<form id="wb-collab-reject-form"><header><div><small>DECLINE</small><h2>拒绝${task.mode==='transfer'?'接管会话':'接收任务'}</h2><p>拒绝原因会同步给${E(task.creator)}，任务不会从原会话中消失。</p></div><button type="button" data-r-action="wb-close-collab-reject" aria-label="关闭">×</button></header><main><section><small>${E(task.title)}</small><p>${E(task.deliverable)}</p></section><label><b>拒绝原因</b><textarea name="reason" required maxlength="300" placeholder="请说明无法接收的原因，方便发起人重新安排。"></textarea></label><label><b>建议承接人 <small>选填</small></b><select name="suggestedAssignee">${suggestions.map(name=>`<option value="${name==='暂无建议'?'':E(name)}">${E(name)}</option>`).join('')}</select></label></main><footer><button type="button" data-r-action="wb-close-collab-reject">取消</button><button type="submit" class="danger">确认拒绝</button></footer></form>`;const form=$('#wb-collab-reject-form');form.onsubmit=event=>{event.preventDefault();const values=Object.fromEntries(new FormData(form)),reason=values.reason.trim();if(!reason)return toast('请填写拒绝原因');task.status='rejected';task.rejectionReason=reason;task.suggestedAssignee=values.suggestedAssignee;task.rejectedAt=Date.now();task.creatorAlert=true;if(task.mode==='transfer')wbChatCollaboration().owner=task.previousOwner||task.creator;awChat().messages.push({role:'assistant',text:`【协作通知】${task.assignee}拒绝了${task.mode==='transfer'?'会话转交':'任务「'+task.title+'」'}。\n原因：${reason}${task.suggestedAssignee?'\n建议改派给：'+task.suggestedAssignee:''}`,time:now()});state.messages=awChat().messages;persist();wbRejectDialog.close();renderAssistant();toast(`已将拒绝原因同步给${task.creator}`);};wbRejectDialog.showModal();form.elements.reason.focus();}
function wbRenderCollaboration(){
 const visible=WB.agentSection==='chat'&&!AW.folder&&assistantShell.dataset.presentation==='page',oldBar=$('#wb-collab-bar'),oldFeed=$('#wb-collab-feed');if(!visible){oldBar?.remove();oldFeed?.remove();wbCollabPanel.classList.remove('open');return;}
 const collab=wbChatCollaboration(),tasks=collab.tasks||[],main=$('#aw-main-scroll'),body=$('#assistant-body');if(!main||!body)return;const bar=oldBar||document.createElement('section');bar.id='wb-collab-bar';bar.innerHTML=`<div><small>当前负责人</small><p class="wb-collab-current"><span>${E(collab.owner.slice(0,1))}</span><b>${E(collab.owner)}</b><em>参与人 ${collab.participants.length}</em></p></div><div class="wb-collab-bar-actions"><button class="solid" data-r-action="wb-open-transfer">${icon('users')}协作</button></div>`;if(!oldBar)main.insertBefore(bar,body);
 const feed=oldFeed||document.createElement('section');feed.id='wb-collab-feed';feed.innerHTML=tasks.length?tasks.slice(0,3).map(wbCollabTaskCard).join(''):'';feed.hidden=!tasks.length;if(!oldFeed)body.after(feed);
 wbCollabPanel.classList.toggle('open',WB.collabPanelOpen);wbCollabPanel.innerHTML=`<header><div><small>COLLABORATION</small><h2>会话协作</h2></div><button data-r-action="wb-collab-close" aria-label="关闭会话协作">×</button></header><section class="wb-collab-owner"><span>${E(collab.owner.slice(0,1))}</span><div><small>当前负责人</small><b>${E(collab.owner)}</b><em>${collab.participants.map(E).join('、')}</em></div></section><section class="wb-collab-actions single"><button data-r-action="wb-open-assign">＋ 分派任务<small>把一部分工作交给成员或 Agent</small></button></section><div class="wb-collab-panel-list"><h3>协作任务 <span>${tasks.length}</span></h3>${tasks.map(task=>`<article><i class="${task.status}"></i><div><b>${E(task.title)}</b><small>${task.mode==='transfer'?'会话转让':'任务分派'} · ${E(task.assignee)} · ${wbCollabStatus(task.status)}</small></div></article>`).join('')||'<p>当前会话还没有协作记录。</p>'}</div>`;
}
R.invoke('wb-open-assign',()=>wbOpenHandoff('assign'));R.invoke('wb-open-transfer',()=>wbOpenConversationTransfer());R.invoke('wb-close-handoff',()=>wbHandoffDialog.close());
R.invoke('wb-collab-panel',()=>{WB.collabPanelOpen=true;wbRenderCollaboration();});R.invoke('wb-collab-close',()=>{WB.collabPanelOpen=false;wbRenderCollaboration();});
R.invoke('wb-collab-accept',button=>{const task=wbFindCollabTask(button.dataset.id);if(!task)return;if(task.mode==='transfer')wbOpenTransferAcceptance(task);else wbSetCollabStatus(task.id,'processing','任务已接收，开始处理');});
R.invoke('wb-close-transfer-accept',()=>wbTransferAcceptDialog.close());
R.invoke('wb-collab-reject',button=>wbOpenRejectTask(button.dataset.id));R.invoke('wb-close-collab-reject',()=>wbRejectDialog.close());
R.invoke('wb-collab-reassign',button=>{const task=wbFindCollabTask(button.dataset.id);if(task)task.mode==='transfer'?wbOpenConversationTransfer(task):wbOpenHandoff('assign',task);});
R.invoke('wb-collab-submit',button=>wbSetCollabStatus(button.dataset.id,'review','结果已提交，等待确认'));
R.invoke('wb-collab-confirm',button=>wbSetCollabStatus(button.dataset.id,'done','协作任务已完成'));
R.invoke('wb-collab-revise',button=>wbSetCollabStatus(button.dataset.id,'processing','已退回修改'));
R.invoke('wb-collab-remind',button=>{const task=wbFindCollabTask(button.dataset.id);if(task)toast(`已提醒${task.assignee}`);});
R.invoke('wb-save-task-asset',button=>{const task=wbFindCollabTask(button.dataset.id);if(!task||task.assetSaved)return;workspace.assetLibrary.unshift({id:uid(),kind:'finished',name:task.title,format:'AI RESULT',meta:'协作任务产出 · 已确认',creator:task.assignee,created:'刚刚',hue:252,tags:['AI 成片','协作产出','已确认']});task.assetSaved=true;persist();renderAssistant();toast('结果已保存至资产库');});
const wbLegacySkills=R.views.skills;R.views.skills=function(){if(page==='ad-agent'&&WB.agentSection==='skills'){WB.skillTab=R.skillTab==='mine'?'mine':'shared';wbRenderAgentPage();}else wbLegacySkills();};
const wbInnerRender=renderAssistant;renderAssistant=function(){wbInnerRender();wbRenderAgentPage();wbRenderCollaboration();wbRenderComposerAgent();};

R.invoke('wb-smart-publish',()=>{sessionStorage.setItem('open-smart-publish','1');location.hash='ad-agent';render();});
R.invoke('wb-intelligent-publish',()=>{sessionStorage.setItem('open-intelligent-publish','1');location.hash='ad-agent';render();});
render();
const apfStyle=document.createElement('link');apfStyle.rel='stylesheet';apfStyle.href=new URL('ad-publish-flow.css',document.baseURI).href;document.head.append(apfStyle);
const apfScript=document.createElement('script');apfScript.src=new URL('ad-publish-flow.js',document.baseURI).href;document.body.append(apfScript);
